function makeFontSrcAbsolute(src) {
  const base = getFontBaseUrl();
  if (!base || base === "null" || base === "undefined") return src;
  return src.replace(/url\(\s*['"]?\//g, `url('${base}/`);
}

const loadCustomFontsForCanvas = async () => {
  try {
    await Promise.race([
      document.fonts.ready,
      new Promise(resolve => setTimeout(resolve, 2000)),
    ]);

    const fontUrls = [
      {
        family: "Kanz al Marjaan",
        sources: [
          "url(/Kanz%20al%20Marjaan/kanz-al-marjaan-webfont.woff2) format('woff2')",
          "url(/Kanz%20al%20Marjaan/kanz-al-marjaan-webfont.woff) format('woff')",
          "url(/Kanz%20al%20Marjaan/kanz-al-marjaan-webfont.ttf) format('truetype')",
        ],
      },
      {
        family: "Al-Kanz",
        sources: [
          "url(/fonts/al-kanz.ttf) format('truetype')",
        ],
      },
      {
        family: "Qilka-Bold",
        sources: [
          "url(/Qilka-Bold.otf) format('opentype')",
        ],
      },
      {
        family: "Child Hood",
        sources: [
          "url(/Child-Hood.otf) format('opentype')",
        ],
      },
    ];

    for (const { family, sources } of fontUrls) {
      const testStr = "abcdefghijklmnopqrstuvwxyz0123456789";
      if (!document.fonts.check(`1em "${family}"`, testStr)) {
        const absoluteSources = sources.map(s => makeFontSrcAbsolute(s));
        const ff = new FontFace(family, absoluteSources.join(", "));
        await ff.load();
        document.fonts.add(ff);
      }
    }

    await Promise.race([
      document.fonts.ready,
      new Promise(resolve => setTimeout(resolve, 3000)),
    ]);
  } catch (err) {
    console.warn("Custom font loading for canvas capture failed:", err);
  }
};

async function captureElementToPdf(elementId, fileName, { scale, onBeforeCapture } = {}) {
  let el = null;
  for (let i = 0; i < 25; i++) {
    await new Promise(r => setTimeout(r, 200));
    el = document.getElementById(elementId);
    if (el && el.offsetParent !== null && el.offsetWidth > 0) break;
    if (el && el.getBoundingClientRect().width > 0) break;
  }
  if (!el) throw new Error(`Element #${elementId} not found`);
  await new Promise(r => setTimeout(r, 600));
  await loadCustomFontsForCanvas();
  if (onBeforeCapture) await onBeforeCapture();
  const [h2c, { jsPDF }] = await Promise.all([
    import("html2canvas").then(m => m.default),
    import("jspdf"),
  ]);
  const captureScale = scale || (window.innerWidth < 768 ? 2.5 : 3);
  const rect = el.getBoundingClientRect();
  const canvas = await captureWithRetry(() => h2c(el, {
    scale: captureScale, useCORS: true, allowTaint: true, backgroundColor: "#ffffff",
    width: rect.width, height: rect.height, logging: false,
    onclone: async (doc) => {
      const s = doc.createElement('style');
      s.textContent = FONT_FACE_CSS;
      doc.head.appendChild(s);
      try { await Promise.race([doc.fonts ? doc.fonts.ready : Promise.resolve(), new Promise(r => setTimeout(r, 4000))]); } catch (e) {}
    },
  }), 3);
  const imgData = canvas.toDataURL("image/jpeg", 0.92);
  if (imgData.length < 5000) throw new Error("Blank capture");
  const pdf = new jsPDF('p', 'mm', 'a4');
  const pw = pdf.internal.pageSize.getWidth(), ph = pdf.internal.pageSize.getHeight();
  const m = 6, mw = pw - m * 2, mh = ph - m * 2;
  const ip = pdf.getImageProperties(imgData);
  const fs = Math.min(mw / ip.width, mh / ip.height);
  const fw = ip.width * fs, fh = ip.height * fs;
  pdf.addImage(imgData, "JPEG", (pw - fw) / 2, (ph - fh) / 2, fw, fh, undefined, 'FAST');
  return pdf.output('blob');
}

