 // TTL-cached global ranks so realtime refreshes / 60s polls don't re-invoke
// the get-global-rank edge function (which scans ALL weekly results) every time.
let globalRanksCache = { data: null, fetchedAt: 0 };
const GLOBAL_RANKS_TTL = 2 * 60 * 1000; // 2 minutes

async function fetchGlobalRanks() {
  if (globalRanksCache.data && Date.now() - globalRanksCache.fetchedAt < GLOBAL_RANKS_TTL) {
    return globalRanksCache.data;
  }
  try {
    const ranksPromise = supabase.functions.invoke("get-global-rank", { body: { return_all: true } });
    const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error("Rank timeout")), 1500));
    const { data, error } = await Promise.race([ranksPromise, timeoutPromise]);
    if (!error && data?.ranks) {
      globalRanksCache = { data, fetchedAt: Date.now() };
    }
    return data || null;
  } catch (_e) {
    return globalRanksCache.data || null;
  }
}

// Prevent stacked full-portal reloads when many realtime events fire at once.
let portalLoadInFlight = false;
// When a reload is requested while another one is still running (e.g. the parent
// switches child mid-refresh), remember that a fresh run is needed so the latest
// child selection is honored instead of being silently dropped.
let portalLoadPending = false;

async function authorizePortalAccess(user, requestedRole) {
  let finalRole = requestedRole;

  // Resolve kibar-teacher and kibar-admin.
  // Step 1: Check JWT metadata (zero Firestore calls, no scope switching).
  const assigned = getAssignedRoles(user);
  if (requestedRole === "teacher" && assigned.includes("kibar-teacher")) {
    finalRole = "kibar-teacher";
  } else if (requestedRole === "admin" && assigned.includes("kibar-admin")) {
    finalRole = "kibar-admin";
  } else if ((requestedRole === "parents" || requestedRole === "kibar-student") && assigned.includes("kibar-student")) {
    finalRole = "kibar-student";
  }

  // Step 2: If metadata didn't reveal kibar role, query kibar_user_portal_access
  // DIRECTLY by its full hardcoded name
  if ((requestedRole === "teacher" && finalRole === "teacher") ||
      (requestedRole === "admin"   && finalRole === "admin")) {
    try {
      const { data: kibarRow } = await supabase
        .from("kibar_user_portal_access")
        .select("*")
        .eq("id", user.id)
        .maybeSingle();
      if (kibarRow?.is_active) {
        if (kibarRow.portal_role === "kibar-teacher" && requestedRole === "teacher") {
          finalRole = "kibar-teacher";
        } else if (kibarRow.portal_role === "kibar-admin" && requestedRole === "admin") {
          finalRole = "kibar-admin";
        }
      }
    } catch (_) {}
  }

  setSectionScope(SECTION_FOR_ROLE(finalRole));
  let tableAccess = await findPortalAccess(user.id);
  // Also check kibar_user_portal_access if tableAccess is empty
  if (!tableAccess && finalRole.startsWith("kibar-")) {
    try {
      const { data: kibarDirect } = await supabase
        .from("kibar_user_portal_access")
        .select("*")
        .eq("id", user.id)
        .maybeSingle();
      if (kibarDirect) tableAccess = kibarDirect;
    } catch (_) {}
  }

  const assignedRoles = getAssignedRoles(user);
  const requestedLabel = ROLE_LABELS[finalRole] || finalRole;

  // Unified Admin access: Any admin (Atfal Admin or Kibar Admin) has access to both admin views!
  const isAdminRole = finalRole === "admin" || finalRole === "kibar-admin";
  const userHasAdminAccess = (tableAccess?.is_active && (tableAccess.portal_role === "admin" || tableAccess.portal_role === "kibar-admin")) ||
    assignedRoles.includes("admin") || assignedRoles.includes("kibar-admin");

  if (isAdminRole && userHasAdminAccess) {
    return {
      ok: true,
      role: finalRole,
      assignedRoles: [...new Set([...assignedRoles, finalRole])],
      parentProfile: null,
      accessRow: tableAccess || null,
    };
  }

  if (tableAccess?.is_active && tableAccess.portal_role === finalRole) {
    return {
      ok: true,
      role: finalRole,
      assignedRoles: [finalRole],
      parentProfile: null,
      accessRow: tableAccess,
    };
  }

  // Allow admin access if teacher's email is in teacher_admin_access list
  if (isAdminRole && user?.email) {
    try {
      const targetTable = finalRole === "kibar-admin" ? "kibar_jadwal_settings" : "jadwal_settings";
      const { data: settingsData } = await supabase
        .from(targetTable)
        .select('teacher_admin_access')
        .eq('id', 1)
        .maybeSingle();
      let accessList = [];
      if (settingsData?.teacher_admin_access) {
        try {
          accessList = typeof settingsData.teacher_admin_access === 'string'
            ? JSON.parse(settingsData.teacher_admin_access)
            : settingsData.teacher_admin_access;
        } catch (_) {}
      }
      if ((!accessList || accessList.length === 0) && finalRole === "kibar-admin") {
        try {
          const { data: atfalSettings } = await supabase
            .from('jadwal_settings')
            .select('teacher_admin_access')
            .eq('id', 1)
            .maybeSingle();
          if (atfalSettings?.teacher_admin_access) {
            accessList = typeof atfalSettings.teacher_admin_access === 'string'
              ? JSON.parse(atfalSettings.teacher_admin_access)
              : atfalSettings.teacher_admin_access;
          }
        } catch (_) {}
      }
      if (Array.isArray(accessList) && accessList.some(e =>
        normalizeText(e) === normalizeText(user.email) || normalizeText(e) === normalizeText(user.id)
      )) {
        return {
          ok: true,
          role: finalRole,
          assignedRoles: [...new Set([...assignedRoles, finalRole])],
          parentProfile: null,
          accessRow: tableAccess || null,
        };
      }
    } catch (_) {}
  }

  if (tableAccess?.is_active && tableAccess.portal_role && tableAccess.portal_role !== finalRole) {
    return {
      ok: false,
      message: `This account is assigned to the ${ROLE_LABELS[tableAccess.portal_role] || tableAccess.portal_role
        } portal in Supabase. It cannot open the ${requestedLabel} portal.`,
    };
  }

  if (finalRole === "parents" || finalRole === "kibar-student") {
    let parentProfiles = [];
    if (finalRole === "kibar-student") {
      // Kibar Student: fetch own profile directly from kibar_student_profiles / child_profiles
      const studentProfile = await findKibarStudentProfile(user.id, user.email);
      if (studentProfile) {
        parentProfiles = [studentProfile];
      } else {
        try {
          parentProfiles = await findKibarParentProfiles(user.id, user.email);
        } catch (_) {}
        if (!parentProfiles || parentProfiles.length === 0) {
          parentProfiles = await findKibarParentProfilesFallback(user.id, user.email);
        }
      }

      // Safe fallback profile: ONLY for users genuinely assigned to kibar-student
      if (!parentProfiles || parentProfiles.length === 0) {
        if (assignedRoles.includes("kibar-student") || user?.user_metadata?.portal_role === "kibar-student" || user?.user_metadata?.role === "kibar-student") {
          parentProfiles = [{
            id: user.id,
            user_id: user.id,
            name: user.user_metadata?.full_name || user.user_metadata?.name || user.email?.split('@')[0] || "Student",
            full_name: user.user_metadata?.full_name || user.user_metadata?.name || user.email?.split('@')[0] || "Student",
            student_id: user.user_metadata?.student_id || user.user_metadata?.its || user.id,
            its: user.user_metadata?.its || user.user_metadata?.its_number || "...",
            section: "kibar",
            is_kibar: true
          }];
        }
      }
    } else {
      try {
        parentProfiles = await findParentProfiles(user.id, user.email);
      } catch (_) {}
      if (!parentProfiles || parentProfiles.length === 0) {
        parentProfiles = await findParentProfilesFallback(user.id, user.email);
      }
      // If not found in Atfal profiles, check Kibar student profiles!
      if (!parentProfiles || parentProfiles.length === 0) {
        try {
          const kibarProf = await findKibarStudentProfile(user.id, user.email);
          if (kibarProf) {
            parentProfiles = [kibarProf];
            finalRole = "kibar-student";
            setSectionScope("kibar");
          } else {
            const kibarParent = await findKibarParentProfiles(user.id, user.email);
            if (kibarParent && kibarParent.length > 0) {
              parentProfiles = kibarParent;
              finalRole = "kibar-student";
              setSectionScope("kibar");
            }
          }
        } catch (_) {}
      } else if (parentProfiles.some(p => p.is_kibar || p.section === "kibar")) {
        finalRole = "kibar-student";
        setSectionScope("kibar");
      }
    }

    if (parentProfiles.length > 0) {
      return {
        ok: true,
        role: finalRole,
        assignedRoles: assignedRoles.length > 0 ? assignedRoles : [finalRole],
        parentProfile: parentProfiles[0],
        allParentProfiles: parentProfiles,
        accessRow: tableAccess || null,
      };
    }
  }

  if (tableAccess && !tableAccess.is_active) {
    return {
      ok: false,
      message: "This account exists in Supabase portal access, but it is currently inactive.",
    };
  }

  if (assignedRoles.length > 0) {
    return {
      ok: false,
      message: `This account is assigned to ${formatRoleList(
        assignedRoles
      )}. It cannot open the ${requestedLabel} portal.`,
    };
  }

  return {
    ok: false,
    message: `This account is not assigned to the ${requestedLabel} portal yet. Add a role in Supabase user metadata first.`,
  };
}

async function resolveInitialPortal(user, preferredRole) {
  if (!user) return { ok: false, message: "No user provided" };

  const assigned = getAssignedRoles(user);
  let storedRole = null;
  try {
    storedRole = localStorage.getItem(STORAGE_KEYS.role) || localStorage.getItem("mauze-portal-role");
  } catch (_) {}

  // 1. If preferredRole or storedRole is specified, try that first:
  let candidateRole = preferredRole || storedRole;

  if (candidateRole === "teacher" && assigned.includes("kibar-teacher")) {
    candidateRole = "kibar-teacher";
  } else if (candidateRole === "admin" && assigned.includes("kibar-admin")) {
    candidateRole = "kibar-admin";
  } else if (candidateRole === "parents" && (assigned.includes("kibar-student") || user?.user_metadata?.portal_role === "kibar-student")) {
    candidateRole = "kibar-student";
  }

  if (candidateRole) {
    setSectionScope(SECTION_FOR_ROLE(candidateRole));
    const access = await authorizePortalAccess(user, candidateRole);
    if (access.ok) {
      return access;
    }
  }

  // 2. Check user_portal_access / kibar_user_portal_access table
  try {
    if (candidateRole && candidateRole.startsWith("kibar-")) {
      const { data: kibarAccess } = await supabase
        .from("kibar_user_portal_access")
        .select("*")
        .eq("id", user.id)
        .maybeSingle();
      if (kibarAccess?.is_active && kibarAccess.portal_role) {
        const access = await authorizePortalAccess(user, kibarAccess.portal_role);
        if (access.ok) return access;
      }
    }

    const atfalAccess = await findPortalAccess(user.id);
    if (atfalAccess?.is_active && atfalAccess.portal_role) {
      const access = await authorizePortalAccess(user, atfalAccess.portal_role);
      if (access.ok) return access;
    }
    const { data: kibarAccess } = await supabase
      .from("kibar_user_portal_access")
      .select("*")
      .eq("id", user.id)
      .maybeSingle();
    if (kibarAccess?.is_active && kibarAccess.portal_role) {
      const access = await authorizePortalAccess(user, kibarAccess.portal_role);
      if (access.ok) return access;
    }
  } catch (_) {}

  // 3. Try explicitly assigned roles in metadata
  for (const role of assigned) {
    const access = await authorizePortalAccess(user, role);
    if (access.ok) return access;
  }

  // 4. Try parents (Atfal)
  const parentAccess = await authorizePortalAccess(user, "parents");
  if (parentAccess.ok) return parentAccess;

  // 5. Try kibar-student ONLY if user has a kibar student profile
  try {
    const kibarProfile = await findKibarStudentProfile(user.id, user.email);
    if (kibarProfile) {
      const kibarAccess = await authorizePortalAccess(user, "kibar-student");
      if (kibarAccess.ok) return kibarAccess;
    }
  } catch (_) {}

  // 6. Try teacher (Atfal)
  const teacherAccess = await authorizePortalAccess(user, "teacher");
  if (teacherAccess.ok) return teacherAccess;

  // 7. Try admin (Atfal)
  const adminAccess = await authorizePortalAccess(user, "admin");
  if (adminAccess.ok) return adminAccess;

  return {
    ok: false,
    message: "No active portal assignment found for this account.",
  };
}

function guessTeacherIdentity(user, portalAccess = null) {
  if (portalAccess?.full_name) return portalAccess.full_name;

  const metadataName =
    user?.user_metadata?.teacher_name ||
    user?.user_metadata?.full_name ||
    user?.user_metadata?.name;

  if (metadataName) return metadataName;

  return (user?.email || "")
    .split("@")[0]
    .replace(/[._-]+/g, " ")
    .trim();
}

function getStudentStatus(student) {
  if (student?.latestResult?.attendance_note) {
    return student.latestResult.attendance_note;
  }

  if (student?.hifz?.teacher_note) {
    return student.hifz.teacher_note;
  }

  if (student?.hifz?.surat) {
    return `Memorizing ${student.hifz.surat}`;
  }

  return "Status update pending";
}

const READ_DAY_ORDER = ['SATURDAY','SUNDAY','MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY'];
const READ_DAY_LABELS = { SATURDAY:'Saturday', SUNDAY:'Sunday', MONDAY:'Monday', TUESDAY:'Tuesday', WEDNESDAY:'Wednesday', THURSDAY:'Thursday', FRIDAY:'Friday' };

const getWeekDateStr = (dayIndex) => {
  const now = new Date();
  const today = now.getDay(); // 0=Sunday, 6=Saturday
  const daysSinceSat = (today + 1) % 7; // Saturday=6, (6+1)%7=0
  const saturday = new Date(now);
  saturday.setDate(now.getDate() - daysSinceSat);
  const d = new Date(saturday);
  d.setDate(saturday.getDate() + dayIndex);
  // Return ISO date string for reliable parsing
  return d.toISOString().split('T')[0];
};

function ReadJadwalView({ scheduleData, mode, editHistory }) {
  // Map JS getDay (0=Sun..6=Sat) to our Saturday=0..Friday=6 order
  const todayIndex = [1,2,3,4,5,6,0][new Date().getDay()];
  return (
    <div className="jadwal-table-wrapper">
      <table className="jadwal-table">
        <thead>
          {mode === 'juz-wise' ? (
            <>
              <tr>
                <th rowSpan="2">Day</th>
                <th colSpan="4" style={{ textAlign: 'center' }}>
                  <div style={{ display: 'inline-flex', alignItems: 'center', gap: 6, justifyContent: 'center' }}>
                    <BookOpen size={14} /> <span>Murajah</span>
                  </div>
                </th>
                <th rowSpan="2"><span>Jadeed</span></th>
                <th rowSpan="2"><span>Juzhali</span></th>
                <th rowSpan="2"><span>Total</span></th>
              </tr>
              <tr>
                <th>1</th><th>2</th><th>3</th><th>4</th>
              </tr>
            </>
          ) : (
            <tr>
              <th>Day</th>
              <th><span>Murajah</span></th>
              <th><span>Jadeed</span></th>
              <th><span>Juzhali</span></th>
              <th><span>Total</span></th>
            </tr>
          )}
        </thead>
        <tbody>
          {READ_DAY_ORDER.map((day, idx) => {
            const row = scheduleData[day] || {};
            const isToday = idx === todayIndex;
            const weekDate = getWeekDateStr(idx);
            const fatemiInfo = weekDate ? getFatemiInfo(weekDate) : null;
            const fatemiDateStr = fatemiInfo && fatemiInfo.monthName ? `${fatemiInfo.date} ${fatemiInfo.monthName} ${fatemiInfo.year}` : '';
            return (
              <tr key={day} className={isToday ? 'read-jadwal-today-row' : ''}>
                <td className={`day-cell ${isToday ? 'read-jadwal-today-day' : ''}`}>
                  <div className="day-cell-content">
                    <span className="day-cell-name">{READ_DAY_LABELS[day]}</span>
                    {fatemiDateStr && <div className="day-fatemi-date">{fatemiDateStr}</div>}
                  </div>
                </td>
                {mode === 'juz-wise' ? (
                  <>
                    {['juz1','juz2','juz3','juz4'].map((juz, ji) => (
                      <td key={juz} data-label={`Juz ${ji + 1}`} className={getCellEdited(editHistory, day, juz) ? 'jadwal-cell-edited' : ''}>
                        <span style={{ fontFamily: "'Al-Kanz', 'Kanz al Marjaan', serif", direction: 'rtl', fontSize: 14 }}>{toArabicNum(row[juz] || '') || '-'}</span>
                      </td>
                    ))}
                    <td data-label="Jadeed" className={getCellEdited(editHistory, day, 'jadeed') ? 'jadwal-cell-edited' : ''}>
                      <span style={{ fontFamily: "'Al-Kanz', 'Kanz al Marjaan', serif", direction: 'rtl', fontSize: 14 }}>{formatJadeed(row.jadeed)}</span>
                    </td>
                    <td data-label="Juzhali" className={getCellEdited(editHistory, day, 'juzhali') ? 'jadwal-cell-edited' : ''}>
                      <span style={{ fontFamily: "'Al-Kanz', 'Kanz al Marjaan', serif", direction: 'rtl', fontSize: 14 }}>{formatJuzhali(row.juzhali)}</span>
                    </td>
                    <td data-label="Total" className="star-cell">
                      <span style={{ fontWeight: 700, color: '#d4af37', fontSize: 16 }}>{calcTotalPages(row, mode)} Pages</span>
                    </td>
                  </>
                ) : (
                  <>
                    <td data-label="Murajah" className={getCellEdited(editHistory, day, 'murajah') ? 'jadwal-cell-edited' : ''}>
                      <span style={{ fontFamily: "'Al-Kanz', 'Kanz al Marjaan', serif", direction: 'rtl', fontSize: 14 }}>{formatMurajah(row.murajah)}</span>
                    </td>
                    <td data-label="Jadeed" className={getCellEdited(editHistory, day, 'jadeed') ? 'jadwal-cell-edited' : ''}>
                      <span style={{ fontFamily: "'Al-Kanz', 'Kanz al Marjaan', serif", direction: 'rtl', fontSize: 14 }}>{formatJadeed(row.jadeed)}</span>
                    </td>
                    <td data-label="Juzhali" className={getCellEdited(editHistory, day, 'juzhali') ? 'jadwal-cell-edited' : ''}>
                      <span style={{ fontFamily: "'Al-Kanz', 'Kanz al Marjaan', serif", direction: 'rtl', fontSize: 14 }}>{formatJuzhali(row.juzhali)}</span>
                    </td>
                    <td data-label="Total" className="star-cell">
                      <span style={{ fontWeight: 700, color: '#d4af37', fontSize: 16 }}>{calcTotalPages(row, mode)} Pages</span>
                    </td>
                  </>
                )}
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

function buildStudents(childProfiles = [], weeklyResults = [], teacherProfiles = []) {
  const resultsByWeek = {};
  weeklyResults.forEach(r => {
    if (!r.week_date) return;
    if (!resultsByWeek[r.week_date]) resultsByWeek[r.week_date] = [];
    resultsByWeek[r.week_date].push(r);
  });

  const rankMap = new Map();
  Object.keys(resultsByWeek).forEach(week => {
    const weekResults = resultsByWeek[week];
    const sorted = [...weekResults].sort((a, b) => {
      const scoreDiff = calculateEffectiveScore(b) - calculateEffectiveScore(a);
      if (scoreDiff !== 0) return scoreDiff;
      const jadeedDiff = (Number(b.jadeed) || 0) - (Number(a.jadeed) || 0);
      if (jadeedDiff !== 0) return jadeedDiff;
      const jadeedPagesADiff = (Number(String(b.total_jadeed_pages ?? "").replace(/[^0-9.]/g, "")) || 0) - (Number(String(a.total_jadeed_pages ?? "").replace(/[^0-9.]/g, "")) || 0);
      if (jadeedPagesADiff !== 0) return jadeedPagesADiff;
      return (Number(b.attendance_count) || 0) - (Number(a.attendance_count) || 0);
    });

    let prevRank = 1;
    sorted.forEach((result, idx) => {
      let currentRank = idx + 1;
      if (idx > 0) {
        const prev = sorted[idx - 1];
        if (
          calculateEffectiveScore(prev) === calculateEffectiveScore(result) &&
          (Number(prev.jadeed) || 0) === (Number(result.jadeed) || 0) &&
          (Number(String(prev.total_jadeed_pages ?? "").replace(/[^0-9.]/g, "")) || 0) === (Number(String(result.total_jadeed_pages ?? "").replace(/[^0-9.]/g, "")) || 0) &&
          (Number(prev.attendance_count) || 0) === (Number(result.attendance_count) || 0)
        ) {
          currentRank = prevRank;
        }
      }
      prevRank = currentRank;
      const resId = String(result.student_id || "").trim().toLowerCase();
      rankMap.set(`${resId}-${week}`, currentRank);
    });
  });

  const latestResultMap = new Map();
  const sortedByDate = [...weeklyResults].sort((a, b) => new Date(b.week_date || 0) - new Date(a.week_date || 0));

  sortedByDate.forEach((result) => {
    const resId = String(result.student_id || "").trim().toLowerCase();
    if (resId && !latestResultMap.has(resId)) {
      const weeklyRank = rankMap.get(`${resId}-${result.week_date}`);
      latestResultMap.set(resId, { ...result, weeklyRank, effectiveScore: calculateEffectiveScore(result) });
    }
    const resName = normalizeText(result.student_name || result.name || result.full_name || "");
    if (resName && !latestResultMap.has(`name:${resName}`)) {
      latestResultMap.set(`name:${resName}`, { ...result, effectiveScore: calculateEffectiveScore(result) });
    }
  });

  const previousRankMap = new Map();
  const seenStudents = new Set();
  sortedByDate.forEach((result) => {
    const resId = String(result.student_id || "").trim().toLowerCase();
    if (resId) {
      if (!seenStudents.has(resId)) {
        seenStudents.add(resId);
      } else if (!previousRankMap.has(resId)) {
        const prevRank = rankMap.get(`${resId}-${result.week_date}`);
        if (prevRank) previousRankMap.set(resId, prevRank);
      }
    }
  });

  // Deduplicate childProfiles by student_id or id or name so identical rows are unified
  const dedupedProfiles = [];
  const seenStudentKeys = new Set();
  (childProfiles || []).forEach((profile) => {
    if (!profile) return;
    const sId = profile.student_id || profile.its || profile.id;
    const sName = normalizeText(profile.full_name || profile.name || "");
    const dedupKey = sId ? `id:${String(sId).trim().toLowerCase()}` : `name:${sName}`;
    if (!seenStudentKeys.has(dedupKey)) {
      seenStudentKeys.add(dedupKey);
      dedupedProfiles.push({ ...profile });
    } else {
      const existingIdx = dedupedProfiles.findIndex(p => {
        const pId = p.student_id || p.its || p.id;
        const pName = normalizeText(p.full_name || p.name || "");
        return (sId && String(pId).trim().toLowerCase() === String(sId).trim().toLowerCase()) || (sName && pName === sName);
      });
      if (existingIdx !== -1) {
        dedupedProfiles[existingIdx] = {
          ...profile,
          ...dedupedProfiles[existingIdx],
          teacher_id: dedupedProfiles[existingIdx].teacher_id || profile.teacher_id || profile.muhaffiz_id,
          muhaffiz_id: dedupedProfiles[existingIdx].muhaffiz_id || profile.muhaffiz_id || profile.teacher_id,
          teacher_name: dedupedProfiles[existingIdx].teacher_name || profile.teacher_name || profile.muhaffiz_name,
          parent_user_id: dedupedProfiles[existingIdx].parent_user_id || profile.parent_user_id || profile.user_id,
          parent_email: dedupedProfiles[existingIdx].parent_email || profile.parent_email,
        };
      }
    }
  });

  const builtStudents = dedupedProfiles.map((profile) => {
    const sId = profile.student_id || profile.its || profile.id;
    const numericId = !isNaN(sId) ? Number(sId) : sId;
    
    const normalizeId = (id) => String(id || "").trim().toLowerCase();
    const pId = normalizeId(profile.id);
    const psId = normalizeId(profile.student_id);
    const pIts = normalizeId(profile.its);
    const pName = normalizeText(profile.full_name || profile.name || "");

    const allCandidateIds = [pId, psId, pIts, ...(profile.allIds || []).map(normalizeId)].filter(Boolean);

    const latestResult = 
      allCandidateIds.map(id => latestResultMap.get(id)).find(Boolean) ||
      (pName && latestResultMap.get(`name:${pName}`)) ||
      (Array.from(latestResultMap.values()).find(r => 
        (profile.full_name && r.full_name && normalizeText(r.full_name) === normalizeText(profile.full_name)) ||
        (profile.name && r.name && normalizeText(r.name) === normalizeText(profile.name)) ||
        (profile.name && r.student_name && normalizeText(r.student_name) === normalizeText(profile.name)) ||
        (profile.full_name && r.student_name && normalizeText(r.student_name) === normalizeText(profile.full_name))
      )) || null;

    // Support multiple possible teacher ID field names (kibar vs atfal)
    const teacherId = profile.teacher_id || profile.muhaffiz_id || profile.teacher_user_id || profile.teacherId;
    const teacherInProfiles = teacherProfiles.find(t =>
      (teacherId && (t.id === teacherId || t.user_id === teacherId))
    );

    const prevWeekRank = latestResult ? (() => {
      const lrId = String(latestResult.student_id || "").trim().toLowerCase();
      return previousRankMap.get(lrId) || null;
    })() : null;

    return {
      ...profile,
      id: profile.id,
      student_id: numericId,
      allIds: [profile.student_id, profile.its, profile.id, profile.user_id, profile.parent_user_id].filter(Boolean).map(String),
      name: profile.full_name,
      arabic_name: fixArabicScript(profile.arabic_name),
      its: profile.its || "...",
      latestResult,
      previousWeekRank: prevWeekRank,
      teacherName: profile.teacher_name || profile.muhaffiz_name || teacherInProfiles?.full_name || "Unassigned teacher",
      groupName: profile.group_name || "Ungrouped",
      muhaffiz_id: profile.teacher_id || profile.muhaffiz_id || profile.teacher_user_id || profile.teacherId || null,
      /* Badal fields: original_teacher_id = permanent teacher, badal_teacher_id = substitute (nullable) */
      original_teacher_id: profile.original_teacher_id || null,
      badal_teacher_id: profile.badal_teacher_id || null,
      user_id: profile.parent_user_id || null,
      parent_email: profile.parent_email || null,
      photoUrl: cleanPhotoUrl(profile.photo_url || ""),
      whatsapp_number: profile.whatsapp_number || "",
      hifz: {
        juz: profile.juz || "N-A",
        surat: profile.surat || "Pending",
      },
      hifzStatus: profile.surat ? `Memorizing ${profile.surat}` : "Status pending",
    };
  });

  const rankable = [...builtStudents.filter(s => s.latestResult)];
  rankable.sort((a, b) => {
    const scoreA = calculateEffectiveScore(a.latestResult);
    const scoreB = calculateEffectiveScore(b.latestResult);
    const scoreDiff = scoreB - scoreA;
    if (scoreDiff !== 0) return scoreDiff;
    const jadeedDiff = (Number(b.latestResult.jadeed) || 0) - (Number(a.latestResult.jadeed) || 0);
    if (jadeedDiff !== 0) return jadeedDiff;
    const jadeedPagesADiff = (Number(String(b.latestResult.total_jadeed_pages ?? "").replace(/[^0-9.]/g, "")) || 0) - (Number(String(a.latestResult.total_jadeed_pages ?? "").replace(/[^0-9.]/g, "")) || 0);
    if (jadeedPagesADiff !== 0) return jadeedPagesADiff;
    return (Number(b.latestResult.attendance_count) || 0) - (Number(a.latestResult.attendance_count) || 0);
  });

  let globalPrevRank = 1;
  rankable.forEach((s, idx) => {
    let currentRank = idx + 1;
    if (idx > 0) {
      const prev = rankable[idx - 1];
      const scorePrev = calculateEffectiveScore(prev.latestResult);
      const scoreCurr = calculateEffectiveScore(s.latestResult);
      if (
        scorePrev === scoreCurr &&
        (Number(prev.latestResult.jadeed) || 0) === (Number(s.latestResult.jadeed) || 0) &&
        (Number(String(prev.latestResult.total_jadeed_pages ?? "").replace(/[^0-9.]/g, "")) || 0) === (Number(String(s.latestResult.total_jadeed_pages ?? "").replace(/[^0-9.]/g, "")) || 0) &&
        (Number(prev.latestResult.attendance_count) || 0) === (Number(s.latestResult.attendance_count) || 0)
      ) {
        currentRank = globalPrevRank;
      }
    }
    globalPrevRank = currentRank;
    s.latestResult.computedRank = currentRank;
  });

  return builtStudents;
}

const recalculateComputedRanks = (students) => {
  const withScores = students
    .filter(s => s.latestResult)
    .map(s => ({
      ...s,
      _effScore: calculateEffectiveScore(s.latestResult),
      _jadeed: Number(s.latestResult.jadeed) || 0,
      _jadeedPages: Number(String(s.latestResult.total_jadeed_pages ?? "").replace(/[^0-9.]/g, "")) || 0,
      _attendance: Number(s.latestResult.attendance_count) || 0,
    }));
  withScores.sort((a, b) => {
    const scoreDiff = b._effScore - a._effScore;
    if (scoreDiff !== 0) return scoreDiff;
    const jadeedDiff = b._jadeed - a._jadeed;
    if (jadeedDiff !== 0) return jadeedDiff;
    const jadeedPagesDiff = b._jadeedPages - a._jadeedPages;
    if (jadeedPagesDiff !== 0) return jadeedPagesDiff;
    return b._attendance - a._attendance;
  });
  const studentRanks = {};
  let prevRank = 1;
  withScores.forEach((s, idx) => {
    let currentRank = idx + 1;
    if (idx > 0) {
      const prev = withScores[idx - 1];
      if (prev._effScore === s._effScore && prev._jadeed === s._jadeed && prev._jadeedPages === s._jadeedPages && prev._attendance === s._attendance) {
        currentRank = prevRank;
      }
    }
    prevRank = currentRank;
    studentRanks[String(s.student_id)] = currentRank;
  });
  if (Object.keys(studentRanks).length === 0) return students;
  return students.map(s => {
    const sid = String(s.student_id);
    const newRank = studentRanks[sid];
    if (newRank && s.latestResult) {
      return { ...s, latestResult: { ...s.latestResult, computedRank: newRank } };
    }
    return s;
  });
};

class PortalErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null };
  }
  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }
  componentDidCatch(error, info) {
    console.error("PortalErrorBoundary caught:", error, info);
  }
  render() {
    if (this.state.hasError) {
      return (
        <div style={{ padding: '40px', textAlign: 'center', fontFamily: 'system-ui, sans-serif' }}>
          <h2 style={{ color: '#e74c3c', marginBottom: '12px' }}>Something went wrong</h2>
          <p style={{ color: '#666', marginBottom: '8px' }}>The portal could not be loaded. Please try refreshing the page.</p>
          <p style={{ color: '#999', fontSize: '0.85rem' }}>{this.state.error?.message || 'Unknown error'}</p>
          <button
            onClick={() => { this.setState({ hasError: false, error: null }); window.location.reload(); }}
            style={{ marginTop: '20px', padding: '10px 24px', background: '#3498db', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontSize: '1rem' }}
          >
            Refresh Page
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}

function LoadingScreen({ message, onComplete }) {
  const [phase, setPhase] = useState(1);
  const completedRef = useRef(false);
  useEffect(() => {
    const t = setTimeout(() => {
      setPhase(2);
      if (!completedRef.current) {
        completedRef.current = true;
        if (onComplete) onComplete();
      }
    }, 100);
    return () => { clearTimeout(t); };
  }, [onComplete]);
  return (
    <div className="splash-screen">
      <div className="splash-logo-container">
        <svg viewBox="0 0 400 400" className="splash-svg" xmlns="http://www.w3.org/2000/svg">
          <defs>
            <linearGradient id="splashGold" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stopColor="#d4af37" />
              <stop offset="50%" stopColor="#f5e6a3" />
              <stop offset="100%" stopColor="#b8941f" />
            </linearGradient>
            <linearGradient id="splashGold2" x1="0%" y1="100%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="#b8941f" />
              <stop offset="50%" stopColor="#f5e6a3" />
              <stop offset="100%" stopColor="#d4af37" />
            </linearGradient>
          </defs>
          <circle cx="200" cy="200" r="160" fill="none" stroke="url(#splashGold)" strokeWidth="2"
            className="splash-path" strokeDasharray="1005" strokeDashoffset="1005"
            style={{ animation: 'splashTrace 0.5s ease-out forwards' }} />
          <circle cx="200" cy="200" r="140" fill="none" stroke="url(#splashGold2)" strokeWidth="1"
            className="splash-path" strokeDasharray="880" strokeDashoffset="880"
            style={{ animation: 'splashTrace 0.5s ease-out 0.15s forwards' }} />
          <path d="M 200 80 L 200 320" fill="none" stroke="url(#splashGold)" strokeWidth="1.5"
            className="splash-path" strokeDasharray="240" strokeDashoffset="240"
            style={{ animation: 'splashTrace 0.3s ease-out 0.3s forwards' }} />
          <path d="M 140 200 L 260 200" fill="none" stroke="url(#splashGold)" strokeWidth="1.5"
            className="splash-path" strokeDasharray="120" strokeDashoffset="120"
            style={{ animation: 'splashTrace 0.3s ease-out 0.45s forwards' }} />
          <circle cx="200" cy="200" r="60" fill="none" stroke="url(#splashGold)" strokeWidth="1.5"
            className="splash-path" strokeDasharray="377" strokeDashoffset="377"
            style={{ animation: 'splashTrace 0.4s ease-out 0.55s forwards' }} />
        </svg>
        <div className="splash-logo-inner">
          <img src="/atfal logo splash.png" alt="" className="splash-logo-img visible" />
        </div>
      </div>
      <h1 className="splash-title visible">روضة الأطفال</h1>
      <p className="splash-subtitle visible">Mauze Tahfeez</p>
      <div className={`splash-loader ${phase >= 2 ? 'done' : ''}`}>
        <div className="splash-loader-bar" />
      </div>
      <p className="splash-message visible">{message || 'Loading...'}</p>
    </div>
  );
}

function StudentAvatar({ student, size = "regular" }) {
  const [imgFailed, setImgFailed] = useState(false);
  if (student?.photoUrl && !imgFailed) {
    return (
      <img
        src={student.photoUrl}
        alt={student.name || "Student"}
        className={`student-avatar ${size}`}
        onError={() => setImgFailed(true)}
      />
    );
  }

  return (
    <div className={`avatar-placeholder ${size === "small" ? "small" : ""}`}>
      <User size={size === "small" ? 20 : 28} />
    </div>
  );
}

