            <circle cx="17" cy="17" r="15" fill="none" stroke="rgba(46, 196, 182, 0.2)" strokeWidth="3" />
            <circle 
              cx="17" 
              cy="17" 
              r="15" 
              fill="none" 
              stroke="#2ec4b6" 
              strokeWidth="3" 
