                          borderRadius: '12px',
                          border: 'none',
                          cursor: 'pointer',
                          fontWeight: 700,
                          fontSize: '0.95rem',
                          fontFamily: 'Inter, sans-serif',
                          letterSpacing: '0.3px',
                          transition: 'all 0.2s ease',
                          background: leaveEnabled
