                        padding: '16px 20px',
                        borderRadius: '16px',
                        background: 'linear-gradient(135deg, rgba(217, 119, 6, 0.12), rgba(180, 83, 9, 0.06))',
                        border: '1.5px solid rgba(217, 119, 6, 0.45)',
                        boxShadow: '0 8px 24px rgba(217, 119, 6, 0.18), 0 0 16px rgba(217, 119, 6, 0.2)',
