  const lastPortalRoleRef = useRef(portalRole);
  useEffect(() => {
    // Only switch activePage if portalRole actually changed
    if (lastPortalRoleRef.current !== portalRole) {
      lastPortalRoleRef.current = portalRole;
      const savedPages = readSavedPages();
      const restoredPage = savedPages[portalRole];
      setActivePage(restoredPage || DEFAULT_PAGE_BY_ROLE[portalRole] || DEFAULT_PAGE_BY_ROLE.parents);
    }
    setMenuOpen(false);
    setActionMessage(null);

    // When switching to admin role, reload data via get_all_child_profiles RPC
    // to bypass RLS (teachers toggled for admin access would otherwise see only their students).
    // On initial login, user is null here so this won't double-load.
    if (!isFirstRender.current && user && (portalRole === "admin" || portalRole === "kibar-admin")) {
      setLoading(true);
      loadPortalData(portalRole, user).catch(() => {
        if (typeof setLoading === 'function') setLoading(false);
      });
    }

    // Check URL for redirectPage from notification click outside the app
    const params = new URLSearchParams(window.location.search);
    const redirectFromNotif = params.get('redirectPage');
    if (redirectFromNotif) {
      let targetPage = redirectFromNotif;
      if (targetPage.startsWith("Jadwal:")) {
        const parts = targetPage.split(":");
        if (parts[1]) {
          setSelectedStudentId(parts[1]);
        }
        targetPage = "Jadwal";
      }
      setActivePage(resolveRedirectPage(targetPage, portalRole));
      const notifLeaveId = params.get('leaveId');
      if (notifLeaveId) setPendingChatLeaveId(notifLeaveId);
      const notifStudentId = params.get('studentId');
      if (notifStudentId) {
        setSelectedStudentId(notifStudentId);
        try {
          localStorage.setItem("mauze-selected-child", notifStudentId);
        } catch (_) {}
      }
      const openAppIntent = params.get('openApp');
      if (openAppIntent === 'true' && typeof navigator !== 'undefined' && /Android/i.test(navigator.userAgent)) {
        // If opened from external browser, try to launch app intent with Play Store fallback
        const intentUrl = `intent://mouze-tahfeez-atfal.vercel.app/?redirectPage=${encodeURIComponent(targetPage)}&studentId=${notifStudentId || ''}#Intent;scheme=https;package=com.mauzetahfeez.myapp;S.browser_fallback_url=${encodeURIComponent("https://play.google.com/store/apps/details?id=com.mauzetahfeez.myapp")};end`;
        try {
          window.location.href = intentUrl;
        } catch (_) {}
      }
      // Clean URL without the redirect parameter
      window.history.replaceState({}, '', window.location.pathname);
    }
  }, [portalRole]);

  useEffect(() => {
    // Native-app deep link: consume a stashed notification tap (cold-start or
    // background) and navigate to the exact page the notification belongs to —
    // without a full page reload.
    const applyNotifTap = () => {
      if (!user || loading) return; // portal not ready yet — re-run when ready
      let tap = null;
      try {
        const raw = localStorage.getItem(NOTIF_TAP_KEY);
        if (raw) tap = JSON.parse(raw);
      } catch (_) {}
      if (!tap && window.MauzeNotifBridge && typeof window.MauzeNotifBridge.getPendingNotifTap === "function") {
        try {
          const raw = window.MauzeNotifBridge.getPendingNotifTap();
          if (raw) tap = JSON.parse(raw);
        } catch (_) {}
      }
      if (!tap) return;
      // Clear immediately — single consumption.
      try { localStorage.removeItem(NOTIF_TAP_KEY); } catch (_) {}
      try {
        if (window.MauzeNotifBridge && typeof window.MauzeNotifBridge.clearPendingNotifTap === "function") {
          window.MauzeNotifBridge.clearPendingNotifTap();
        }
      } catch (_) {}

      let targetPage = tap.redirectPage || tap.redirect_page || "";
      let targetStudentId = tap.studentId || tap.student_id || "";
      if (!targetPage && typeof tap.url === "string" && tap.url.includes("redirectPage=")) {
        try {
          targetPage = decodeURIComponent(tap.url.split("redirectPage=")[1].split("&")[0]);
        } catch (_) {}
      }
      if (!targetPage || targetPage === "/" || targetPage === "null") return;
      if (String(targetPage).startsWith("Jadwal:")) {
        const parts = String(targetPage).split(":");
        targetPage = parts[0];
        if (parts[1]) targetStudentId = parts[1];
      }
      const resolved = resolveRedirectPage(targetPage, portalRole);
      if (resolved) {
        if (targetStudentId) setSelectedStudentId(targetStudentId);
        setActivePage(resolved);
        setActionMessage(null);
        if (tap.leaveId) setPendingChatLeaveId(String(tap.leaveId));
      }
    };

    const handleSwMessage = (event) => {
      if (event?.data?.type === "mauze:notification-click") {
        const notifData = event.data.data || {};
        try {
          localStorage.setItem(NOTIF_TAP_KEY, JSON.stringify(notifData));
        } catch (_) {}
        applyNotifTap();
      }
    };

    applyNotifTap();
    window.addEventListener("mauze:notification-tap", applyNotifTap);
    if (typeof navigator !== "undefined" && "serviceWorker" in navigator) {
      navigator.serviceWorker.addEventListener("message", handleSwMessage);
    }

    return () => {
      window.removeEventListener("mauze:notification-tap", applyNotifTap);
      if (typeof navigator !== "undefined" && "serviceWorker" in navigator) {
        navigator.serviceWorker.removeEventListener("message", handleSwMessage);
      }
    };
  }, [portalRole, user, loading]);

  useEffect(() => {
    writeSavedPage(portalRole, activePage);
  }, [activePage, portalRole]);

  useEffect(() => {
    // Handle credential storage from eLearning site
    const handleMessage = (event) => {
      if (event.origin === ELEARNING_ORIGIN && event.data.type === 'STORE_CREDENTIALS') {
        const { email, password, rememberMe } = event.data.credentials;
        localStorage.setItem('elearning-email', email);
        localStorage.setItem('elearning-password', password);
        localStorage.setItem('elearning-remember-me', rememberMe.toString());
      }
    };

    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, []);

  useEffect(() => {
    let mounted = true;

    const failsafe = setTimeout(() => {
      if (mounted) setLoading(false);
    }, 3500);

    // CACHE-FIRST STARTUP: Synchronously restore user + role + cached portal data
    // from localStorage BEFORE any network call, so returning users see their last
    // page instantly with no loading screen. Network data then refreshes silently.
    function restoreCacheSync() {
      try {
        const cachedRaw = localStorage.getItem(STORAGE_KEYS.cachedAuth);
        if (!cachedRaw) return null;
        const cached = JSON.parse(cachedRaw);
        if (!cached.userId || !cached.role) return null;

        setUser({ id: cached.userId, email: cached.email });
        storeRole(cached.role);
        setPortalAccess(emptyPortalAccess);

        try {
          const cacheRaw = localStorage.getItem('mauze_portal_cache');
          if (cacheRaw) {
            const cacheData = JSON.parse(cacheRaw);
            if (cacheData.role === cached.role || ((cached.role === 'kibar-student' || cached.role === 'parents') && (cacheData.role === 'parents' || cacheData.role === 'kibar-student'))) {
              if ((cached.role === 'parents' || cached.role === 'kibar-student') && cacheData.parentData) {
                setParentData(cacheData.parentData);
              } else if (cacheData.schoolData) {
                setSchoolData(cacheData.schoolData);
              }
            }
          }
        } catch (_) {}

        setLoading(false);
        return cached;
      } catch (_) {
        return null;
      }
    }

    async function tryRestoreCachedAuth(retries = 2) {
      const cachedRaw = localStorage.getItem(STORAGE_KEYS.cachedAuth);
      if (!cachedRaw) return false;
      try {
        const cached = JSON.parse(cachedRaw);
        if (!cached.userId || !cached.role) return false;

        // Re-authenticate with Supabase if no valid session exists, so subsequent
        // loadPortalData queries (which require RLS auth) don't fail.
        const { data: sessionData } = await supabase.auth.getSession().catch(() => ({ data: { session: null } }));
        if (!sessionData?.session) {
          const savedEmail = localStorage.getItem("mauze-saved-email");
          const savedPassword = localStorage.getItem("mauze-saved-password");
          if (savedEmail && savedPassword) {
            const { error: signInError } = await supabase.auth.signInWithPassword({
              email: savedEmail,
              password: savedPassword,
            });
            if (signInError) return false;
          } else {
            return false;
          }
        }

        setUser({ id: cached.userId, email: cached.email });
        storeRole(cached.role);

        // Restore cached data instantly while fresh data loads
        try {
          const cachedRaw = localStorage.getItem('mauze_portal_cache');
          if (cachedRaw) {
            const cacheData = JSON.parse(cachedRaw);
            if ((cacheData.role === cached.role || ((cached.role === 'kibar-student' || cached.role === 'parents') && (cacheData.role === 'parents' || cacheData.role === 'kibar-student'))) && Date.now() - cacheData._t < 86400000) {
              if ((cached.role === 'parents' || cached.role === 'kibar-student') && cacheData.parentData) {
                setParentData(cacheData.parentData);
              } else if (cacheData.schoolData) {
                setSchoolData(cacheData.schoolData);
              }
              setLoading(false);
            }
          }
        } catch (_) {}

        for (let attempt = 0; attempt <= retries; attempt++) {
          try {
            await loadPortalData(cached.role, { id: cached.userId, email: cached.email }, null, { silent: true });
            return true;
          } catch (e) {
            console.warn(`Offline: portal data unavailable (attempt ${attempt + 1}/${retries + 1})`, e);
            if (attempt < retries) {
              await new Promise(resolve => setTimeout(resolve, 2000 * (attempt + 1)));
            }
          }
        }
        return false;
      } catch (e) {
        return false;
      }
    }

    async function initialize() {
      // OTP flag in sessionStorage persists across page refreshes (no OTP prompt)
      // but is automatically cleared when the tab/browser closes (OTP prompt shown).
      // localStorage keeps a copy for tryRestoreCachedAuth fallback.
      // Cache-first: restore instantly so returning users never see a loading screen.
      const cacheRestored = restoreCacheSync();

      // Check session FIRST before deleting tokens
      let session = null;
      try {
        const res = await supabase.auth.getSession();
        session = res?.data?.session ?? null;
      } catch (e) {
        console.warn("Session check failed", e);
      }

      if (!mounted) return;

      if (session) {
        if (cacheRestored) {
          // Portal already rendered from cache — just refresh data silently.
          handleAuthChange("INITIAL_SESSION", session, { silent: true });
          return;
        }
        handleAuthChange("INITIAL_SESSION", session);
        return;
      }

      // Try token refresh (tokens still in localStorage)
      try {
        const { data: { session: refreshedSession } } = await supabase.auth.refreshSession();
        if (refreshedSession && mounted) {
          if (cacheRestored) {
            handleAuthChange("SIGNED_IN", refreshedSession, { silent: true });
            return;
          }
          handleAuthChange("SIGNED_IN", refreshedSession);
          return;
        }
      } catch (e) {
        console.warn("Token refresh failed, falling back to cached auth:", e);
      }

      if (!mounted) return;

      // Fall back to cached auth
      const restored = await tryRestoreCachedAuth();
      if (!restored && mounted) {
        if (!cacheRestored) {
          setUser(null);
        }
        setLoading(false);
      }
    }

    async function handleAuthChange(event, session, options = {}) {
      if (!mounted) return;

      // Determine if the current session matches the cached user auth to enable silent operation
      const cachedRaw = localStorage.getItem(STORAGE_KEYS.cachedAuth);
      let isCached = false;
      if (cachedRaw) {
        try {
          const cached = JSON.parse(cachedRaw);
          if (cached.userId && cached.role && session && session.user && cached.userId === session.user.id) {
            isCached = true;
          }
        } catch (_) {}
      }

      const silent = options.silent || isCached;

      // Prevent portal flicker by showing loading screen during role resolution,
      // unless we already rendered the portal from cache (silent background refresh).
      if (!silent) setLoading(true);

      if (session) {
        setUser(session.user);
        try {
          const currentStoredRole = window.localStorage.getItem(STORAGE_KEYS.role) || "parents";
          const access = await resolveInitialPortal(
            session.user,
            currentStoredRole
          );

          if (mounted) {
            if (!access || !access.ok) {
              console.warn("Portal resolution returned non-ok, using currentStoredRole safely:", access?.message);
              const fallbackRole = currentStoredRole || "parents";
              storeRole(fallbackRole);
              setPortalAccess(emptyPortalAccess);
              loadPortalData(fallbackRole, session.user, null, { silent }).catch(() => {});
              if (!silent) setLoading(false);
              return;
            }

            storeRole(access.role);
            setPortalAccess(access.accessRow || emptyPortalAccess);

            // Sync App Lock settings from Firebase!
            try {
              supabase.from("app_lock_settings")
                .select("*")
                .eq("user_id", session.user.id)
                .limit(1)
                .then(res => {
                  if (res?.data && res.data.length > 0) {
                    const lockSettings = res.data[0];
                    if (lockSettings.enabled) {
                      localStorage.setItem(APP_LOCK_KEYS.enabled, 'true');
                      if (lockSettings.pin_hash) {
                        localStorage.setItem(APP_LOCK_KEYS.pin, lockSettings.pin_hash);
                      }
                      setAppLockEnabled(true);
                    } else {
                      localStorage.removeItem(APP_LOCK_KEYS.enabled);
                      localStorage.removeItem(APP_LOCK_KEYS.pin);
                      setAppLockEnabled(false);
                    }
                  }
                });
            } catch (syncErr) {
              console.error("Failed to sync app lock from Firebase on login:", syncErr);
            }

            

            // Initialize FCM service once per user + role to prevent duplicate token requests.
            const fcmInitKey = `${session.user.id}:${access.role}`;
            if (fcmInitKeyRef.current !== fcmInitKey) {
              fcmInitKeyRef.current = fcmInitKey;
              try {
                const fcmService = await loadFcmService();
                await fcmService.initialize(access.role);
              } catch (error) {
                fcmInitKeyRef.current = null;
                console.error('FCM initialization failed:', error);
              }
            }

            // Restore cached data instantly while fresh data loads
            let silentFetch = silent;
            try {
              const cachedRaw = localStorage.getItem('mauze_portal_cache');
              if (cachedRaw) {
                const cached = JSON.parse(cachedRaw);
                const isRoleMatch = cached.role === access.role || ((access.role === 'kibar-student' || access.role === 'parents') && (cached.role === 'parents' || cached.role === 'kibar-student'));
                if (isRoleMatch) {
                  if ((access.role === 'parents' || access.role === 'kibar-student') && cached.parentData) {
                    setParentData(cached.parentData);
                  } else if (cached.schoolData) {
                    setSchoolData(cached.schoolData);
                  }
                  setLoading(false);
                } else {
                  // Role has changed! Show loading spinner and fetch new data
                  silentFetch = false;
                  setLoading(true);
                }
              } else {
                silentFetch = false;
                setLoading(true);
              }
            } catch (_) {
              silentFetch = false;
              setLoading(true);
            }

            if (silentFetch) setLoading(false);
            await loadPortalData(access.role, session.user, access.parentProfile, silentFetch ? { silent: true } : undefined);
          }
          } catch (err) {
          console.error("Auth initialization error:", err);
          if (mounted) {
            if (isNetworkError(err)) {
              const cachedRaw = localStorage.getItem(STORAGE_KEYS.cachedAuth);
              if (cachedRaw) {
                try {
                  const cached = JSON.parse(cachedRaw);
                  if (cached.userId === session.user.id) {
                    storeRole(cached.role);
                    setUser(session.user);
                    loadPortalData(cached.role, session.user, null, { silent: true }).catch(() => {});
                    return;
                  }
                } catch (_) {}
              }
            }
            setLoading(false);
          }
        }
      } else {
        if (mounted) {
          setUser(null);
          setPortalAccess(emptyPortalAccess);
          setParentData(emptyParentData);
          setLoading(false);
        }
        // Ensure stale Supabase tokens are cleaned up
        for (const key of Object.keys(localStorage)) {
          if (key.startsWith('sb-')) localStorage.removeItem(key);
        }
      }
    }

    // Register auth listener FIRST so no SIGNED_OUT events are missed
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((event, session) => {
      if (event === 'SIGNED_OUT' || event === 'USER_DELETED') {
        // Clear stale Supabase tokens on sign out
        for (const key of Object.keys(localStorage)) {
          if (key.startsWith('sb-')) localStorage.removeItem(key);
        }
      }

      // Determine if we should handle silently based on cache matching the session
      let isCached = false;
      try {
        const cachedRaw = localStorage.getItem(STORAGE_KEYS.cachedAuth);
        if (cachedRaw) {
          const cached = JSON.parse(cachedRaw);
          if (cached.userId && session?.user && cached.userId === session.user.id) {
            isCached = true;
          }
        }
      } catch (_) {}

      handleAuthChange(event, session, isCached ? { silent: true } : undefined);
    });

    initialize();

    // Keep session alive by refreshing token periodically (every 30 minutes)
    // This prevents auto logout due to token expiry during long sessions
    const sessionKeepAlive = setInterval(() => {
      if (user && mounted) {
        supabase.auth.getSession().then(({ data: { session } }) => {
          if (session) {
            supabase.auth.refreshSession().catch(() => {});
          }
        });
      }
    }, 30 * 60 * 1000);

    function handleOnline() {
      const cachedRaw = localStorage.getItem(STORAGE_KEYS.cachedAuth);
      if (!user && cachedRaw) {
        supabase.auth.getSession().then(res => {
          if (res?.data?.session && mounted) {
            handleAuthChange("SIGNED_IN", res.data.session);
          }
        });
      }
    }
    window.addEventListener('online', handleOnline);

    function handleVisibilityChange() {
      if (document.visibilityState === 'visible' && user && mounted) {
        const cachedRaw = localStorage.getItem(STORAGE_KEYS.cachedAuth);
        if (cachedRaw) {
          try {
            const cached = JSON.parse(cachedRaw);
            loadPortalData(cached.role || portalRole, user, null, { silent: true }).catch(() => {});
          } catch (_) {}
        }
      }
    }
    document.addEventListener('visibilitychange', handleVisibilityChange);

    window.addEventListener('pageshow', function(e) {
      if (e.persisted && user && mounted) {
        const cachedRaw = localStorage.getItem(STORAGE_KEYS.cachedAuth);
        if (cachedRaw) {
          try {
            const cached = JSON.parse(cachedRaw);
            loadPortalData(cached.role || portalRole, user, null, { silent: true }).catch(() => {});
          } catch (_) {}
        }
      }
    });

    return () => {
      mounted = false;
      clearTimeout(failsafe);
      clearInterval(sessionKeepAlive);
      subscription.unsubscribe();
      window.removeEventListener('online', handleOnline);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, []);

  useEffect(() => {
    if (user) {
      const cachedRaw = localStorage.getItem(STORAGE_KEYS.cachedAuth);
      if (cachedRaw) {
        try {
          const cached = JSON.parse(cachedRaw);
          if (cached.role) storeRole(cached.role);
        } catch (_) {}
      }
    }
  }, [user]);

  useEffect(() => {
    if (user && portalRole === "parents" && selectedStudentId) {
      loadPortalData(portalRole, user, null, { silent: true });
    }
  }, [selectedStudentId, portalRole, user]);

  // REALTIME: Listen for backend changes to the key portal tables and update the UI
  // instantly in the background — no manual refresh, no loading screen. Debounced so
  // rapid changes (e.g. a teacher filling many rows) only trigger one refresh.
  useEffect(() => {
    if (!user || !portalRole) return;

    let refreshTimer = null;
    const scheduleRefresh = () => {
      clearTimeout(refreshTimer);
      refreshTimer = setTimeout(() => {
        if (portalLoadInFlight) return;
        loadPortalData(portalRole, user, null, { silent: true }).catch(() => {});
      }, 1200);
    };

    const isKibar = portalRole === "kibar-student";
    const tables = isKibar
      ? ["kibar_weekly_results", "kibar_student_daily_attendance", "kibar_schedule", "kibar_events", "kibar_report_settings", "kibar_jadwal_settings"]
      : portalRole === "parents"
        ? ["weekly_results", "student_daily_attendance", "schedule", "events", "report_settings", "jadwal_settings"]
        : portalRole === "teacher"
          ? ["weekly_results", "student_daily_attendance", "teacher_profiles", "schedule", "events", "report_settings", "jadwal_settings"]
          : ["weekly_results", "student_daily_attendance", "teacher_profiles", "schedule", "events", "report_settings", "jadwal_settings", "portal_access"];

    const channel = supabase.channel(`portal-realtime-${portalRole}`);
    tables.forEach((table) => {
      channel.on(
        "postgres_changes",
        { event: "*", schema: "public", table },
        scheduleRefresh
      );
    });
    channel.subscribe((status) => {
      if (status !== "SUBSCRIBED" && status !== "CHANNEL_ERROR" && status !== "TIMED_OUT") {
        // Keep a fallback poll for browsers/networks without realtime support.
      }
    });

    const fallbackPoll = setInterval(() => {
      if (document.visibilityState === "visible" && !portalLoadInFlight) {
        loadPortalData(portalRole, user, null, { silent: true }).catch(() => {});
      }
    }, 120000);

    return () => {
      clearTimeout(refreshTimer);
      clearInterval(fallbackPoll);
      supabase.removeChannel(channel);
    };
  }, [portalRole, user]);

  async function loadPortalData(role, currentUser, parentProfileOverride = null, { silent = false } = {}) {
    if (!currentUser) {
      setLoading(false);
      return;
    }
    setSectionScope(SECTION_FOR_ROLE(role));

    // NOTE: Do NOT sync selectedStudentIdRef here. The ref is kept current by
    // the effect on [selectedStudentId] and by selectParentChild, and this
    // function may be invoked from an older render closure (background/realtime
    // refreshes, or the click handler) whose selectedStudentId is stale — syncing
    // here would clobber the latest selection and revert the portal to child 1.

    if (portalLoadInFlight) {
      // A full reload is already running. Instead of silently dropping this
      // request (which used to swallow parent child-switch clicks during
      // background refreshes), remember that a fresh run is needed and re-run
      // once the current reload finishes so the newest selection is honored.
      if (silent) {
        portalLoadPending = true;
        return;
      }
    }
    portalLoadInFlight = true;

    if (!silent) setLoading(true);

    try {
      const isKibar = role === "kibar-student";
      if (role === "parents" || isKibar) {
        let rawProfiles = parentProfileOverride ? [parentProfileOverride] : null;
        
        if (isKibar) {
          // Kibar Student: fetch own profile directly from kibar_student_profiles / kibar_child_profiles / child_profiles
          const studentProfile = await findKibarStudentProfile(currentUser.id, currentUser.email);
          if (studentProfile) {
            rawProfiles = [studentProfile];
          }
          // Fallback for kibar student if profile not found
          if (!studentProfile) {
            try {
              rawProfiles = await findKibarParentProfiles(currentUser.id, currentUser.email);
            } catch (_e) {}
            if (!rawProfiles || rawProfiles.length === 0) {
              try {
                const { data, error } = await supabase.rpc("get_my_kibar_child_profiles", {
                  p_user_id: currentUser.id,
                  p_email: currentUser.email || null,
                });
                if (!error && data && data.length > 0) {
                  rawProfiles = data;
                }
              } catch (_e) {}
            }
          }
        } else if (!rawProfiles || rawProfiles.length === 0) {
          try {
            rawProfiles = await findParentProfiles(currentUser.id, currentUser.email);
          } catch (err) {
            console.warn("child_profiles read blocked; using fallback RPC", err);
          }
        }
        
        if (!isKibar && (!rawProfiles || rawProfiles.length === 0)) {
          rawProfiles = await findParentProfilesFallback(currentUser.id, currentUser.email);
        }

        // Check if user is a returning/existing account or has already completed registration
        const localRegDone = (
          localStorage.getItem('mauze_reg_done_' + currentUser.id) === 'true' ||
          localStorage.getItem('mauze_reg_done_' + (currentUser.email || '').toLowerCase()) === 'true' ||
          localStorage.getItem('mauze_first_login_done_' + currentUser.id) === 'true' ||
          localStorage.getItem('mauze_first_login_done_' + (currentUser.email || '').toLowerCase()) === 'true'
        );

        let isRegisteredInDb = false;
        if (!localRegDone) {
          try {
            const { data: accessRecord } = await supabase
              .from(isKibar ? "kibar_portal_access" : "user_portal_access")
              .select("has_completed_registration, created_at, user_id, email")
              .or(`user_id.eq.${currentUser.id},email.eq.${currentUser.email || ''}`)
              .maybeSingle();
            if (accessRecord?.has_completed_registration === true) {
              isRegisteredInDb = true;
            }
          } catch (_) {}
        }

        const isExistingAccount = localRegDone || isRegisteredInDb;

        // If no profiles found:
        // 1. If truly a brand new first-time login (not existing and never completed registration), show mandatory First-Time Registry Modal
        // 2. If existing/returning account, create fallback profile and DO NOT prompt the registration form
        if (!rawProfiles || rawProfiles.length === 0) {
          if (!isExistingAccount) {
            console.log("[Portal] Brand new account without student profile — prompting first-time student registration.");
            setNeedsFirstTimeRegistration(true);
            if (!silent) setLoading(false);
            return;
          } else {
            console.log("[Portal] Existing account with unlinked profile — generating portal session without modal.");
            setNeedsFirstTimeRegistration(false);
            rawProfiles = [{
              id: currentUser.id,
              user_id: currentUser.id,
              name: currentUser.user_metadata?.full_name || currentUser.user_metadata?.name || currentUser.email?.split('@')[0] || (isKibar ? "Student" : "Child"),
              full_name: currentUser.user_metadata?.full_name || currentUser.user_metadata?.name || currentUser.email?.split('@')[0] || (isKibar ? "Student" : "Child"),
              student_id: currentUser.user_metadata?.student_id || currentUser.user_metadata?.its || currentUser.id,
              its: currentUser.user_metadata?.its || currentUser.user_metadata?.its_number || "...",
              section: isKibar ? "kibar" : "atfal",
              is_kibar: isKibar
            }];
          }
        } else {
          setNeedsFirstTimeRegistration(false);
        }

        let nextParentState = {
          studentProfile: null,
          allProfiles: [],
          hifzDetails: null,
          announcements: [],
          schedule: [],
          attendance: null,
          weeklyResult: null,
          teacherProfiles: [],
          reportSettings: null,
        };

        if (rawProfiles && rawProfiles.length > 0) {
          // AUTO-LINK: If any profile only has email but no ID, link it now (only for parents)
          if (!isKibar) {
            const profilesToLink = rawProfiles.filter(p => !p.parent_user_id && p.parent_email && normalizeText(p.parent_email) === normalizeText(currentUser.email));
            if (profilesToLink.length > 0) {
              console.log("Auto-linking parent user_id to student profiles:", profilesToLink.length);
              await Promise.all(profilesToLink.map(p =>
                supabase.from("child_profiles").update({ parent_user_id: currentUser.id }).eq("student_id", p.student_id)
              ));
              profilesToLink.forEach(p => p.parent_user_id = currentUser.id);
            }
          }

          // Fetch necessary data for all potential students
          const studentQueryIds = Array.from(new Set(rawProfiles.flatMap(p => [
            p.student_id,
            p.id,
            p.user_id,
            p.its,
            p.its_number,
            ...(p.allIds || [])
          ]).filter(Boolean).map(String)));

          const [
            attendanceResponse,
            scheduleResponse,
            resultsResponse,
            archiveResultsResponse,
            announcementResponse,
            teacherProfilesResponse,
            fallbackTeacherProfilesResponse,
            reportSettingsResponse,
            jadwalSettingsResponse,
            portalAccessResponse,
          ] = await Promise.all([
            supabase
              .from(isKibar ? "kibar_student_daily_attendance" : "student_daily_attendance")
              .select("*")
              .in("student_id", studentQueryIds)
              .order("attendance_date", { ascending: false }),
            supabase.from(isKibar ? "kibar_schedule" : "schedule").select("*").in("student_id", studentQueryIds).order("task_time", { ascending: true }),
            supabase
              .from(isKibar ? "kibar_weekly_results" : "weekly_results")
              .select("*")
              .limit(5000),
            supabase
              .from(isKibar ? "kibar_weekly_results_archive" : "weekly_results_archive")
              .select("*")
              .limit(5000),
            supabase.from(isKibar ? "kibar_events" : "events").select("*").order("event_date", { ascending: false }).limit(200),
            supabase.from(isKibar ? "kibar_teacher_profiles" : "teacher_profiles").select("*").order("full_name", { ascending: true }),
            Promise.resolve(supabase.from(isKibar ? "teacher_profiles" : "kibar_teacher_profiles").select("*").order("full_name", { ascending: true })).catch(() => ({ data: [] })),
            supabase.from(isKibar ? "kibar_report_settings" : "report_settings").select("*"),
            supabase.from(isKibar ? "kibar_jadwal_settings" : "jadwal_settings").select("*"),
            Promise.resolve(supabase.from(isKibar ? "kibar_portal_access" : "portal_access").select("*")).catch(() => ({ data: [] })),
          ]);

          // Handle potential missing tables (404) or other fetch errors gracefully
          if (attendanceResponse.error && attendanceResponse.error.code !== 'PGRST116' && attendanceResponse.error.status !== 404) {
            console.error("Attendance fetch error:", attendanceResponse.error);
          }
          if (reportSettingsResponse.data) setReportSettings(reportSettingsResponse.data);
          if (jadwalSettingsResponse.data) setJadwalSettings(jadwalSettingsResponse.data);
          if (scheduleResponse.error) throw scheduleResponse.error;
          if (announcementResponse.error) throw announcementResponse.error;

          const rawTeacherProfiles = [
            ...(teacherProfilesResponse.data || []),
            ...(fallbackTeacherProfilesResponse?.data || [])
          ];
          const rawPortalAccess = portalAccessResponse?.data || [];

          const teacherMap = new Map();
          rawTeacherProfiles.forEach(tp => {
            if (!tp) return;
            const key = normalizeText(tp.full_name || tp.name || tp.email || tp.user_id || tp.id || "");
            if (key) {
              teacherMap.set(key, {
                ...tp,
                photo_url: cleanPhotoUrl(tp.photo_url || ""),
                teacher_role: tp.teacher_role || (tp.role && (tp.role.includes('masool') ? 'masool' : tp.role.includes('musaid') ? 'musaid' : 'muhaffiz')) || 'muhaffiz',
                phone_number: tp.phone_number || "",
                whatsapp_number: tp.whatsapp_number || ""
              });
            }
          });

          rawPortalAccess
            .filter(a => {
              const r = (a.portal_role || "").toLowerCase();
              return r.includes('teacher') || r.includes('muhaffiz') || r.includes('masool') || r.includes('musaid') || r.includes('staff');
            })
            .forEach(a => {
              const key = normalizeText(a.full_name || a.email || a.user_id || a.id || "");
              if (key && !teacherMap.has(key)) {
                teacherMap.set(key, {
                  id: a.user_id || a.id,
                  user_id: a.user_id,
                  full_name: a.full_name,
                  email: a.email,
                  photo_url: cleanPhotoUrl(a.photo_url || ""),
                  phone_number: a.phone_number || "",
                  whatsapp_number: a.whatsapp_number || "",
                  teacher_role: (a.portal_role || "").toLowerCase().includes('masool') ? 'masool' : (a.portal_role || "").toLowerCase().includes('musaid') ? 'musaid' : 'muhaffiz',
                  is_active: true
                });
              } else if (key && teacherMap.has(key)) {
                const ex = teacherMap.get(key);
                teacherMap.set(key, {
                  ...ex,
                  phone_number: ex.phone_number || a.phone_number || "",
                  whatsapp_number: ex.whatsapp_number || a.whatsapp_number || "",
                  photo_url: ex.photo_url || cleanPhotoUrl(a.photo_url || ""),
                  teacher_role: ex.teacher_role || ((a.portal_role || "").toLowerCase().includes('masool') ? 'masool' : (a.portal_role || "").toLowerCase().includes('musaid') ? 'musaid' : ex.teacher_role)
                });
              }
            });

          const consolidatedTeacherProfiles = Array.from(teacherMap.values());

          const attendanceData = attendanceResponse.data || [];
          const allWeeklyResults = [
            ...(resultsResponse?.data || []),
            ...(archiveResultsResponse?.data || [])
          ];

          const processedStudents = buildStudents(
            rawProfiles,
            allWeeklyResults,
            consolidatedTeacherProfiles
          );

          // If multiple students, and none selected, use first
          const currentSelectedId = selectedStudentIdRef.current || selectedStudentId;
          const activeStudent = processedStudents.find(p => String(p.student_id) === String(currentSelectedId)) || processedStudents[0];
          
          // Bulletproof search for activeResult using the already matched latestResult from buildStudents
          let activeResult = activeStudent.latestResult;

          // Get global ranks from Edge Function (bypasses RLS) so ALL portals see
          // the exact same global rank as the admin's Rank Preview page
          try {
            const allRanksData = await fetchGlobalRanks();
            if (allRanksData?.ranks) {
              const globalRanks = allRanksData.ranks;
              processedStudents.forEach(s => {
                const sid = String(s.student_id).trim().toLowerCase();
                const globalRank = globalRanks[sid];
                if (globalRank && s.latestResult) {
                  s.latestResult.computedRank = globalRank;
                }
              });
              // Re-find active result after rank override
              const updatedActive = processedStudents.find(p => String(p.student_id) === String(currentSelectedId)) || processedStudents[0];
              activeResult = updatedActive?.latestResult || activeResult;
            }
          } catch (_e) {
            // Fall back to buildStudents rank if network or timeout
          }

          const todayStr = getToday();
          const activeAttendance = (attendanceResponse.data || []).find(a => 
            a.attendance_date === todayStr &&
            activeStudent.allIds.some(aid => String(aid).trim().toLowerCase() === String(a.student_id || "").trim().toLowerCase())
          );
          const activeSchedule = (scheduleResponse.data || []).filter(s => 
            activeStudent.allIds.some(aid =>
              String(aid).trim().toLowerCase() === String(s.student_id || "").trim().toLowerCase() ||
              String(aid).trim().toLowerCase() === String(s.user_id || "").trim().toLowerCase()
            )
          );

          // Compute monthly attendance and jadeed totals for the active student
          const monthStart = new Date();
          monthStart.setDate(1);
          const monthStartStr = monthStart.toISOString().split('T')[0];
          const activeStudentResults = (resultsResponse.data || []).filter(r =>
            activeStudent.allIds.some(aid => String(aid).trim().toLowerCase() === String(r.student_id || "").trim().toLowerCase()) &&
            r.week_date >= monthStartStr
          );
          const monthlyAttendanceCount = activeStudentResults.reduce((sum, r) => sum + (Number(r.attendance_count) || 0), 0);
          const monthlyJadeedTotal = activeStudentResults.reduce((sum, r) => {
            const raw = String(r.total_jadeed_pages ?? "").replace(/[^0-9a-zA-Z\u0600-\u06FF]/g, "").trim();
            const num = parseFloat(raw);
            return sum + (isNaN(num) ? 0 : num);
          }, 0);
          const monthlyJadeedRaw = activeStudentResults.map(r =>
            String(r.total_jadeed_pages ?? "").trim()
          ).filter(Boolean).join(", ");

          nextParentState = {
            studentProfile: activeStudent,
            allProfiles: processedStudents,
            hifzDetails: {
              juz: activeStudent.juz || "--",
              surat: activeStudent.surat || "Pending",
              muhaffiz_name: activeStudent.teacherName || "Pending",
              teacher_note: activeStudent.latestResult?.attendance_note || null,
              monthly_attendance: monthlyAttendanceCount,
              monthly_jadeed: monthlyJadeedTotal || monthlyJadeedRaw,
            },
            announcements: announcementResponse.data || [],
            schedule: activeSchedule,
            attendance: activeAttendance || null,
            weeklyResult: activeResult || null,
            teacherProfiles: consolidatedTeacherProfiles,
            reportSettings: reportSettingsResponse.data || [],
          };

          if (!selectedStudentIdRef.current) { setSelectedStudentId(activeStudent.student_id); }
          // Remember the active child so a page refresh returns to the same child.
          try { localStorage.setItem("mauze-selected-child", String(activeStudent.student_id)); } catch (_) {}
        }

        setParentData(nextParentState);
        setTeacherProfiles(nextParentState.teacherProfiles || []);
        setSchoolData(curr => ({
          ...curr,
          teacherProfiles: nextParentState.teacherProfiles || [],
          portalAccessList: nextParentState.teacherProfiles || curr.portalAccessList || []
        }));
        try { localStorage.setItem('mauze_portal_cache', JSON.stringify({ role: role, parentData: nextParentState, schoolData: null, _t: Date.now() })); } catch (_) {}
      } else {
        // For admin and teacher roles, use get_all_child_profiles RPC (SECURITY DEFINER, bypasses RLS)
        // so teachers and admins can view all assigned students and Badal substitutes without RLS truncation.
        const isKibarAdmin = role === "kibar-admin" || role === "kibar-teacher";
        const profilesPromise = (role === "admin" || role === "teacher" || role === "kibar-admin" || role === "kibar-teacher")
          ? supabase.rpc(isKibarAdmin ? "get_all_kibar_child_profiles" : "get_all_child_profiles")
              .then(({ data, error }) => {
                if (error || !data || data.length === 0) {
                  return supabase.from(isKibarAdmin ? "kibar_child_profiles" : "child_profiles").select("*").order("full_name", { ascending: true });
                }
                return { data, error: null };
              })
              .catch(() =>
                supabase.from(isKibarAdmin ? "kibar_child_profiles" : "child_profiles").select("*").order("full_name", { ascending: true })
              )
          : supabase.from(isKibarAdmin ? "kibar_child_profiles" : "child_profiles").select("*").order("full_name", { ascending: true });

        const [
          profilesResponse,
          resultsResponse,
          eventsResponse,
          scheduleResponse,
          portalAccessResponse,
          groupsResponse,
          attendanceResponse,
          teacherProfilesResponse,
          reportSettingsResponse,
          jadwalSettingsResponse,
          supportTicketsResponse,
          parentViewsResponse,
        ] = await Promise.all([
          profilesPromise,
          supabase.from(isKibarAdmin ? "kibar_weekly_results" : "weekly_results").select("*").order("week_date", { ascending: false }).limit(10000),
          supabase.from(isKibarAdmin ? "kibar_events" : "events").select("*").order("event_date", { ascending: false }).limit(200),
          supabase.from(isKibarAdmin ? "kibar_schedule" : "schedule").select("*").order("task_time", { ascending: true }).limit(5000),
          supabase.from(isKibarAdmin ? "kibar_user_portal_access" : "user_portal_access").select("*").order("created_at", { ascending: false }).then(r => r, () => ({ data: [], error: null })),
          supabase.from(isKibarAdmin ? "kibar_custom_groups" : "custom_groups").select("*").order("group_name", { ascending: true }).then(r => r, () => ({ data: [], error: null })),
          supabase.from(isKibarAdmin ? "kibar_teacher_attendance" : "teacher_attendance").select("*").order("attendance_date", { ascending: false }).limit(2000).then(r => r, () => ({ data: [], error: null })),
          supabase.from(isKibarAdmin ? "kibar_teacher_profiles" : "teacher_profiles").select("*").order("full_name", { ascending: true }),
          supabase.from(isKibarAdmin ? "kibar_report_settings" : "report_settings").select("*"),
          supabase.from(isKibarAdmin ? "kibar_jadwal_settings" : "jadwal_settings").select("*"),
          supabase.from(isKibarAdmin ? "kibar_portal_issues" : "portal_issues").select("*").order("created_at", { ascending: false }).limit(500).then(r => r, () => ({ data: [], error: null })),
          supabase.from(isKibarAdmin ? "kibar_parent_report_views" : "parent_report_views").select("*").limit(2000).then(r => r, () => ({ data: [], error: null })),
        ]);

        let archiveData = [];
        try {
          const { data: archiveResponseData, error: archiveError } = await supabase
            .from(isKibarAdmin ? "kibar_weekly_results_archive" : "weekly_results_archive")
            .select("*")
            .order("week_date", { ascending: false })
            .limit(5000);
          if (!archiveError && archiveResponseData) archiveData = archiveResponseData;
        } catch (_e) {}

        if (supportTicketsResponse?.data) setSupportTickets(supportTicketsResponse.data);

        if (reportSettingsResponse?.data) setReportSettings(reportSettingsResponse.data);
        if (jadwalSettingsResponse?.data) setJadwalSettings(jadwalSettingsResponse.data);

        if (parentViewsResponse && parentViewsResponse.data) {
          setParentViews(parentViewsResponse.data);
        } else {
          setParentViews([]);
        }

        // Only profilesResponse is critical; optional queries failing should not block portal loading.
        if (profilesResponse?.error && (!profilesResponse?.data || profilesResponse.data.length === 0)) {
          console.error("Critical student profiles fetch error:", profilesResponse.error);
          throw new Error("Unable to load student profiles. Please check database permissions.");
        }

        // Enrich teacher profiles with portal-access data (email + salary
        // visibility) and dedupe by user_id. Duplicates happen when a profile
        // was saved before the update-by-id fix (upsert created a second doc
        // under the user_id key) - keeping one row avoids showing two entries.
        const profileByKey = new Map();
        for (const profile of teacherProfilesResponse.data || []) {
          const access = (portalAccessResponse.data || []).find(a => normalizeText(a.full_name) === normalizeText(profile.full_name));
          const enriched = {
            ...profile,
            photo_url: cleanPhotoUrl(profile.photo_url || ""),
            email: profile.email || access?.email || "",
            user_id: profile.user_id || access?.user_id || "",
            salary_per_minute: profile.salary_per_minute || access?.salary_per_minute || 2.3,
            show_salary_card: profile.show_salary_card ?? access?.show_salary_card ?? true
          };
          const key = String(enriched.user_id || "") || String(profile.id || "");
          if (!profileByKey.has(key)) profileByKey.set(key, enriched);
        }
        const enrichedProfiles = [...profileByKey.values()].sort((a, b) =>
          String(a.full_name || "").localeCompare(String(b.full_name || ""))
        );
        setTeacherProfiles(enrichedProfiles);

        const students = buildStudents(
          profilesResponse.data || [],
          resultsResponse.data || [],
          enrichedProfiles
        );

        setTeacherAttendance(attendanceResponse.data || []);
        setCustomGroups(groupsResponse.data || []);

        if (role === "admin") {
          const { data: waData, error: waError } = await supabase
            .from("whatsapp_config")
            .select("*")
            .eq("id", 1)
            .maybeSingle();
          if (waData) setWhatsappConfig(waData);
          else if (waError) console.warn("Failed to load whatsapp_config:", waError.message);
        }

        // Load email settings
        const { data: emailData, error: emailError } = await supabase
          .from("email_settings")
          .select("*")
          .eq("id", 1)
          .maybeSingle();
        if (emailData) setEmailSettings(emailData);
        else if (emailError) console.warn("Failed to load email_settings:", emailError.message);

        // Fetch global ranks from Edge Function (bypasses RLS) so ALL portals see
        // the exact same global rank as the admin's Rank Preview page
        try {
          const allRanksData = await fetchGlobalRanks();
          if (allRanksData?.ranks) {
            const globalRanks = allRanksData.ranks;
            students.forEach(s => {
              const sid = String(s.student_id).trim().toLowerCase();
              const globalRank = globalRanks[sid];
              if (globalRank && s.latestResult) {
                s.latestResult.computedRank = globalRank;
              }
            });
          }
        } catch (_e) {
          // Fall back to buildStudents ranks
        }

        setSchoolData({
          students,
          weeklyResults: resultsResponse.data || [],
          announcements: eventsResponse.data || [],
          schedule: scheduleResponse.data || [],
          portalAccessList: portalAccessResponse.data || [],
          teacherProfiles: enrichedProfiles,
          weeklyResultsArchive: archiveData,
        });
        try { localStorage.setItem('mauze_portal_cache', JSON.stringify({ role, schoolData: { students, weeklyResults: resultsResponse.data || [], announcements: eventsResponse.data || [], schedule: scheduleResponse.data || [], portalAccessList: portalAccessResponse.data || [], teacherProfiles: enrichedProfiles, weeklyResultsArchive: archiveData }, parentData: null, _t: Date.now() })); } catch (_) {}

        if (students.length > 0) {
          if (role !== "admin") {
            setSelectedStudentId((current) => current || students[0].student_id);
          }
          setAdminForms((current) => ({
            ...current,
            schedule: {
              ...current.schedule,
              student_id: current.schedule.student_id || students[0].student_id,
            },
            teacherAttendance: {
              ...current.teacherAttendance,
              teacher_name:
                current.teacherAttendance.teacher_name || students[0].teacherName || "",
            },
          }));
          setTeacherForms((current) => {
            if (current?.result?.student_id) {
              return current;
            }
            const currentSid = students[0]?.student_id;
            if (!currentSid) return current;
            const freshResults = resultsResponse.data || [];
            const matchingResults = freshResults
              .filter(r => String(r.student_id) === String(currentSid))
              .sort((a, b) => new Date(b.week_date || 0) - new Date(a.week_date || 0));
            if (isStudentCleared(currentSid)) {
              return { ...current, result: createTeacherResultDraft({ student_id: currentSid }) };
            }
            const latestResult = matchingResults.length > 0 ? matchingResults[0] : {};
            return {
              ...current,
              result: {
                ...createTeacherResultDraft({ student_id: currentSid }),
                ...latestResult,
                wusool_surah: latestResult?.wusool_surah || "",
                next_week_surah: latestResult?.next_week_surah || "",
                istifadah_surah: latestResult?.istifadah_surah || "",
                student_id: currentSid,
              },
            };
          });
        }
      }
    } catch (error) {
      console.error("Error fetching portal data:", error);
      setActionMessage({
        type: "error",
        text: `Data Error: ${error?.message || "Some data could not be loaded. Please check your table permissions and try again."}`,
      });
    } finally {
      portalLoadInFlight = false;
      if (portalLoadPending) {
        // A child switch (or other update) was requested while we were loading.
        // Re-run once so the latest selection is applied instead of being lost.
        portalLoadPending = false;
        loadPortalData(role, currentUser, parentProfileOverride, { silent: true }).catch(() => {});
      }
      setLoading(false);
    }
  }

  // Switch the active child in the parent portal. Sets state, persists the
  // choice (so page refreshes keep the same child), and forces a data reload
  // that cannot be lost to an in-flight background refresh.
  const selectParentChild = useCallback((childId) => {
    const id = childId ? String(childId) : "";
    selectedStudentIdRef.current = id;
    setSelectedStudentId(id);
    try {
      if (id) localStorage.setItem("mauze-selected-child", id);
      else localStorage.removeItem("mauze-selected-child");
    } catch (_) {}
    if (user && portalRole === "parents") {
      loadPortalData(portalRole, user, null, { silent: true }).catch(() => {});
    }
  }, [user, portalRole]);

  const teacherIdentity = useMemo(() => guessTeacherIdentity(user, portalAccess), [user, portalAccess]);

  const teacherData = useMemo(() => {
    const availableGroups = Array.from(
      new Set(schoolData.students.map((student) => student.groupName).filter(Boolean))
    );

    /*
     * BADAL FLOW - Teacher Portal student visibility
     * A teacher sees a child if ANY of these is true:
     *   1. The teacher is the child's assigned teacher (muhaffiz_id / teacher_id)
     *   2. The teacher is the child's original teacher (original_teacher_id)
     *   3. The teacher is the child's badal/substitute teacher (badal_teacher_id)
     *   4. Fallback: teacher name matches child's teacherName
     *
     * Permissions (applied elsewhere):
     *   - Badal teacher (badal_teacher_id === user.id): can EDIT badal progress
     *   - Original teacher: can only VIEW badal progress on Badal page (read-only)
     */
    /*
     * BADAL FLOW - Build all possible IDs and Names for the current teacher
     * (user.id, user.email, teacherIdentity, portalAccess matches, teacherProfiles matches)
     */
    const rawId = user?.id || teacherIdentity;
    const allTeacherIds = [];
    const allTeacherNames = new Set();

    if (rawId) allTeacherIds.push(String(rawId).trim());
    if (user?.id && teacherIdentity && String(user.id) !== String(teacherIdentity)) allTeacherIds.push(String(teacherIdentity).trim());
    if (user?.email) allTeacherIds.push(String(user.email).trim().toLowerCase());
    if (teacherIdentity) allTeacherNames.add(normalizeText(teacherIdentity));
    if (portalAccess?.full_name) allTeacherNames.add(normalizeText(portalAccess.full_name));

    (Array.isArray(schoolData?.portalAccessList) ? schoolData.portalAccessList : [])
      .filter(a => {
        const m = String(a.user_id) === String(rawId) ||
                  String(a.id) === String(rawId) ||
                  (a.email && user?.email && String(a.email).trim().toLowerCase() === String(user.email).trim().toLowerCase()) ||
                  (a.full_name && teacherIdentity && normalizeText(a.full_name) === normalizeText(teacherIdentity));
        return m;
      })
      .forEach(a => {
        if (a.user_id && !allTeacherIds.includes(String(a.user_id).trim())) allTeacherIds.push(String(a.user_id).trim());
        if (a.id && !allTeacherIds.includes(String(a.id).trim())) allTeacherIds.push(String(a.id).trim());
        if (a.email && !allTeacherIds.includes(String(a.email).trim().toLowerCase())) allTeacherIds.push(String(a.email).trim().toLowerCase());
        if (a.full_name) allTeacherNames.add(normalizeText(a.full_name));
      });

    (Array.isArray(teacherProfiles) ? teacherProfiles : [])
      .filter(p => {
        const m = String(p.user_id) === String(rawId) ||
                  String(p.id) === String(rawId) ||
                  (p.email && user?.email && String(p.email).trim().toLowerCase() === String(user.email).trim().toLowerCase()) ||
                  (p.full_name && teacherIdentity && normalizeText(p.full_name) === normalizeText(teacherIdentity));
        return m;
      })
      .forEach(p => {
        if (p.user_id && !allTeacherIds.includes(String(p.user_id).trim())) allTeacherIds.push(String(p.user_id).trim());
        if (p.id && !allTeacherIds.includes(String(p.id).trim())) allTeacherIds.push(String(p.id).trim());
        if (p.email && !allTeacherIds.includes(String(p.email).trim().toLowerCase())) allTeacherIds.push(String(p.email).trim().toLowerCase());
        if (p.full_name) allTeacherNames.add(normalizeText(p.full_name));
      });

    const matchedStudents = (portalRole === "admin" || portalRole === "kibar-admin")
      ? [...schoolData.students]
      : schoolData.students.filter((student) => {
          const idMatch = allTeacherIds.some(uid => {
            const u = String(uid).trim().toLowerCase();
            return (
              (student.muhaffiz_id && String(student.muhaffiz_id).trim().toLowerCase() === u) ||
              (student.teacher_id && String(student.teacher_id).trim().toLowerCase() === u) ||
              (student.original_teacher_id && String(student.original_teacher_id).trim().toLowerCase() === u) ||
              (student.badal_teacher_id && String(student.badal_teacher_id).trim().toLowerCase() === u)
            );
          });
          const nameMatch = Array.from(allTeacherNames).some(name =>
            (student.teacherName && normalizeText(student.teacherName) === name) ||
            (student.teacher_name && normalizeText(student.teacher_name) === name) ||
            (student.muhaffiz_name && normalizeText(student.muhaffiz_name) === name)
          );
          /* Also try matching badal_teacher_id or teacher_id against user email as a fallback */
          const emailMatch = !idMatch && user?.email && (
            (student.badal_teacher_id && normalizeText(student.badal_teacher_id) === normalizeText(user.email)) ||
            (student.teacher_id && normalizeText(student.teacher_id) === normalizeText(user.email)) ||
            (student.muhaffiz_id && normalizeText(student.muhaffiz_id) === normalizeText(user.email))
          );
          return idMatch || nameMatch || emailMatch;
        });

    const filteredStudents = [...matchedStudents].sort((a, b) => {
      const cA = isStudentCleared(a.student_id);
      const cB = isStudentCleared(b.student_id);
      if (cA && cB) return String(a.name || "").localeCompare(String(b.name || ""));
      if (cA) return 1;
      if (cB) return -1;
      const rA = a.latestResult?.computedRank;
      const rB = b.latestResult?.computedRank;
      if (rA && rB) return rA - rB;
      if (rA) return -1;
      if (rB) return 1;
      return 0;
    });

    return {
      availableGroups,
      teacherIdentity,
      selectedGroup: teacherGroupFilter,
      filteredStudents,
      attendances: teacherAttendance,
    };
  }, [schoolData, teacherGroupFilter, teacherIdentity, teacherAttendance, portalRole, teacherProfiles, user]);

  const monthlySalary = useMemo(() => {
    if (portalRole !== "teacher") return null;

    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const monthAttendance = (teacherData.attendances || []).filter((a) => {
      const d = new Date(a.attendance_date);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    const totalMinutes = monthAttendance.reduce((sum, a) => sum + toNumber(a.minutes_present), 0);
    const teacherProfile = (teacherProfiles || []).find(p =>
      normalizeText(p.full_name) === normalizeText(teacherIdentity)
    );
    const rate = toNumber(teacherProfile?.salary_per_minute || portalAccess.salary_per_minute || 2.3);
    const showCard = teacherProfile ? !!teacherProfile.show_salary_card : !!portalAccess.show_salary_card;

    return {
      totalMinutes,
      rate,
      amount: totalMinutes * rate,
      daysPresent: monthAttendance.length,
      showCard
    };
  }, [teacherData.attendances, portalAccess.salary_per_minute, portalAccess.show_salary_card, portalRole, teacherProfiles, teacherIdentity]);

  function storeRole(role, newActivePage = null) {
    const targetSection = SECTION_FOR_ROLE(role);
    setPortalRole(role);
    setSectionScope(targetSection);

    // Choose appropriate landing page for the new role to avoid stale subpages from previous role
    const savedPages = readSavedPages();
    const defaultPage = (role === "admin" || role === "kibar-admin")
      ? "Overview"
      : "Home";
    const targetPage = newActivePage || savedPages[role] || defaultPage;
    setActivePage(targetPage);
    writeSavedPage(role, targetPage);

    if (typeof window !== "undefined") {
      window.localStorage.setItem(STORAGE_KEYS.role, role);
      try {
        const cachedRaw = localStorage.getItem(STORAGE_KEYS.cachedAuth);
        if (cachedRaw) {
          const cached = JSON.parse(cachedRaw);
          cached.role = role;
          localStorage.setItem(STORAGE_KEYS.cachedAuth, JSON.stringify(cached));
        }
      } catch (_) {}
    }

    if (user) {
      loadPortalData(role, user, null, { silent: true }).catch(err => {
        console.warn("Failed to load portal data on role switch:", err);
      });
    }
  }

  function showAction(type, text) {
    setActionMessage({ type, text });
    if (type && text) {
      setTimeout(() => {
        setActionMessage(current => {
          if (current?.type === type && current?.text === text) {
            return null;
          }
          return current;
        });
      }, 4000);
    }
  }

  function isNetworkError(err) {
    if (!err) return false;
    const msg = (err.message || err.name || '').toLowerCase();
    return msg.includes('fetch') || msg.includes('network') || msg.includes('networkerror') ||
      msg.includes('typeerror') || msg.includes('failed to fetch') || msg.includes('internet') ||
      err.name === 'TypeError' || err.code === 'NETWORK_ERROR';
  }

  const handleLoginSuccess = async (loggedInUser, selectedRole, rememberMe = true) => {
    try {
      let access = await authorizePortalAccess(loggedInUser, selectedRole);

      if (!access.ok) {
        const resolved = await resolveInitialPortal(loggedInUser, selectedRole);
        if (resolved.ok) {
          access = resolved;
        }
      }

      if (!access.ok) {
        await supabase.auth.signOut();
        return {
          ok: false,
          message: access.message,
        };
      }

      storeRole(access.role);
      setPortalAccess(access.accessRow || emptyPortalAccess);
      setUser(loggedInUser);
      loadPortalData(access.role, loggedInUser, access.parentProfile).catch(() => {});

      if (rememberMe) {
        localStorage.setItem(STORAGE_KEYS.rememberMe, "true");
        localStorage.setItem(STORAGE_KEYS.cachedAuth, JSON.stringify({
          userId: loggedInUser.id,
          email: loggedInUser.email,
          role: access.role,
        }));
      } else {
        localStorage.removeItem(STORAGE_KEYS.rememberMe);
        localStorage.removeItem(STORAGE_KEYS.cachedAuth);
      }

      return { ok: true };
    } catch (error) {
      console.error("Portal authorization failed:", error);

      if (isNetworkError(error)) {
        const cachedRaw = localStorage.getItem(STORAGE_KEYS.cachedAuth);
        if (cachedRaw) {
          try {
            const cached = JSON.parse(cachedRaw);
            if (cached.userId === loggedInUser.id || cached.email === loggedInUser.email) {
              storeRole(cached.role || selectedRole);
              setUser(loggedInUser);
              loadPortalData(cached.role || selectedRole, loggedInUser).catch(() => {});
              return { ok: true };
            }
          } catch (_) {}
        }
        return {
          ok: false,
          message: "Unable to connect. Signed in but could not verify portal access. Please try again when connected.",
        };
      }

      await supabase.auth.signOut();
      return {
        ok: false,
        message: "We could not verify this account for the selected portal.",
      };
    }
  };

  const handleLogout = async () => {
    try {
      const fcm = await import("./fcmService").then(m => m.default);
      await fcm.removeToken();
    } catch (e) { /* ignore */ }

    setUser(null);
    setNeedsFirstTimeRegistration(false);
    setPortalRole("parents");
    setSectionScope("atfal");
    setActivePage("Home");
    setPortalAccess(emptyPortalAccess);
    setParentData(emptyParentData);
    setSchoolData({
      students: [],
      weeklyResults: [],
      announcements: [],
      schedule: [],
      portalAccessList: [],
      weeklyResultsArchive: [],
    });
    showAction(null, null);

    try {
      await supabase.auth.signOut();
    } catch (err) {
      console.warn("Logout error:", err);
    }
    // Preserve saved credentials so "Remember Me" still works on next visit
    const savedEmail = localStorage.getItem("mauze-saved-email");
    const savedPassword = localStorage.getItem("mauze-saved-password");
    const savedRole = localStorage.getItem("mauze-saved-role");
    const rememberMe = localStorage.getItem("mauze-remember-me");
    
    // Clear user auth and portal caches
    localStorage.removeItem(STORAGE_KEYS.role);
    localStorage.removeItem(STORAGE_KEYS.cachedAuth);
    localStorage.removeItem("mauze_portal_cache");
    localStorage.removeItem("parent-jadwal-tracked-days");
    localStorage.removeItem("parent-quick-action-statuses");
    localStorage.removeItem("mauze-selected-child");
    sessionStorage.clear();

    if (rememberMe === "true") {
      if (savedEmail) localStorage.setItem("mauze-saved-email", savedEmail);
      if (savedPassword) localStorage.setItem("mauze-saved-password", savedPassword);
      if (savedRole) localStorage.setItem("mauze-saved-role", savedRole);
      localStorage.setItem("mauze-remember-me", "true");
    }
    setLoading(false);
  };

  const handleAppUnlock = () => {
    setAppLocked(false);
    setAppLockedState(false);
  };

  const handleAppLockToggle = async (enable, pin = null) => {
    if (!enable) {
      localStorage.removeItem(APP_LOCK_KEYS.enabled);
      localStorage.removeItem(APP_LOCK_KEYS.pin);
      setAppLockedState(false);
      setAppLockEnabled(false);
      setAppLocked(false);
      showAction('success', 'App lock disabled.');

      if (user?.id) {
        try {
          await supabase.from("app_lock_settings").upsert({
            user_id: user.id,
            enabled: false,
            pin_hash: "",
            updated_at: new Date().toISOString()
          });
        } catch (dbErr) {
          console.error("Failed to sync app lock disabled to Firebase:", dbErr);
        }
      }
    } else {
      localStorage.setItem(APP_LOCK_KEYS.enabled, 'true');
      if (pin) {
        localStorage.setItem(APP_LOCK_KEYS.pin, hashPin(pin));
      }
      setAppLockedState(false);
      setAppLockEnabled(true);
      setAppLocked(false);

      if (user?.id && pin) {
        try {
          await supabase.from("app_lock_settings").upsert({
            user_id: user.id,
            enabled: true,
            pin_hash: hashPin(pin),
            updated_at: new Date().toISOString()
          });
        } catch (dbErr) {
          console.error("Failed to sync app lock enabled to Firebase:", dbErr);
        }
      }
    }
  };

  const handleCreatePortalAccess = async (event) => {
    event.preventDefault();

    const payload = adminForms.portalAccess;
    const targetEmail = payload.email.trim().toLowerCase();

    const tempAuthClient = createClient(supabaseUrl, supabaseAnonKey, {
      auth: {
        persistSession: false,
        autoRefreshToken: false,
        detectSessionInUrl: false,
      },
    });

    const { data: authData, error: authError } = await tempAuthClient.auth.signUp({
      email: targetEmail,
      password: payload.password,
      options: {
        data: {
          full_name: payload.full_name,
          portal_role: payload.portal_role,
        },
      },
    });

    if (authError && !authError.message.toLowerCase().includes("already registered")) {
      showAction("error", `Auth Error: ${authError.message}`);
      return;
    }

    let createdUserId = authData?.user?.id || null;

    if (!createdUserId) {
      const { data: lookupData } = await supabase.rpc('get_user_id_by_email', { target_email: targetEmail });
      if (lookupData) createdUserId = lookupData;
    }

    let accessRecord = null;
    if (createdUserId) {
      const { data, error: upsertError } = await supabase
        .from("user_portal_access")
        .upsert({
          user_id: createdUserId,
          email: targetEmail,
          full_name: payload.full_name,
          portal_role: payload.portal_role,
          is_active: true
        }, { onConflict: 'user_id' })
        .select()
        .maybeSingle();

      if (upsertError) {
        console.error("Portal access upsert failed:", upsertError);
        showAction("error", `Portal access failed: ${upsertError.message}`);
        return;
      }
      accessRecord = data || null;

      // Keep `users/{uid}` in sync so Firestore rules (role()) can resolve this
      // account's portal_role. New users get this doc server-side from
      // provisionUser, but already-registered accounts need it written here too.
      const nowIso = new Date().toISOString();
      await supabase
        .from("users")
        .upsert({
          id: createdUserId,
          email: targetEmail,
          full_name: payload.full_name,
          portal_role: payload.portal_role,
          is_active: true,
          salary_per_minute: payload.portal_role === "teacher" ? 2.3 : 0,
          show_salary_card: payload.portal_role === "teacher",
          created_at: nowIso,
          updated_at: nowIso
        }, { onConflict: 'id' })
        .then(r => {
          if (r.error) console.warn("users doc upsert failed:", r.error);
        });
    } else {
      const { data, error: fetchError } = await supabase
        .from("user_portal_access")
        .select("*")
        .eq("email", targetEmail)
        .maybeSingle();

      if (fetchError) {
        console.error("Portal access lookup failed:", fetchError);
        showAction("error", `Portal access lookup failed: ${fetchError.message}`);
        return;
      }
      accessRecord = data || null;
    }

    const finalUserId = accessRecord?.user_id || createdUserId || null;

    if (payload.portal_role === "parents" && payload.student_id && finalUserId) {
      await supabase
        .from("child_profiles")
        .update({ parent_user_id: finalUserId })
        .eq("student_id", payload.student_id);
    }

    const { data: freshList, error: refreshError } = await supabase
      .from("user_portal_access")
      .select("*")
      .order("created_at", { ascending: false });

    if (refreshError) {
      console.error("Error refreshing portal list:", refreshError);
    }

    if (freshList) {
      setSchoolData((current) => ({
        ...current,
        portalAccessList: freshList,
      }));
    }

    setAdminForms((current) => ({
      ...current,
      portalAccess: { email: "", full_name: "", portal_role: "parents", password: "", student_id: "" },
    }));

    let linkedStudentName = "Not linked";
    if (payload.student_id) {
      const { data: stData } = await supabase
        .from("child_profiles")
        .select("name")
        .eq("student_id", payload.student_id)
        .maybeSingle();
      if (stData?.name) linkedStudentName = stData.name;
    }

    (async () => {
      try {
        const notifTitle = payload.portal_role === "teacher" ? "New Student Assigned" : "Portal Access Granted";
        const notifBody = payload.portal_role === "teacher" 
          ? `${linkedStudentName} has been assigned to your group.` 
          : `Welcome! ${linkedStudentName} has been successfully linked to your portal account.`;

        broadcastNotification(notifTitle, notifBody, payload.portal_role, finalUserId || targetEmail);
      } catch (e) {
        console.warn("Assignment notification failed:", e);
      }
    })();

    setPortalAccessSuccess({
      full_name: payload.full_name,
      email: targetEmail,
      portal_role: payload.portal_role,
      linkedStudentName,
      grantedAt: new Date().toLocaleString(),
    });

    showAction("success", "Portal access granted successfully!");
  };

  const [notificationsList, setNotificationsList] = useState([]);
  const [scheduledNotifs, setScheduledNotifs] = useState([]);
  const [editingSchedule, setEditingSchedule] = useState(null);
  const [activeStatusAlert, setActiveStatusAlert] = useState(null);
  const [selectedAnnouncement, setSelectedAnnouncement] = useState(null);
  const latestNotifIdRef = useRef(null);

  useEffect(() => {
    if (!user) return;

    // Fetch both notification history and scheduled
    fetchScheduledNotifs();

    let notificationChannel;
    let isActive = true;
    
    const setupNotifications = async () => {
      try {
        // 1. Initial Fetch of History
        const { data } = await supabase
          .from("system_notifications")
          .select("*")
          .order("created_at", { ascending: false })
          .limit(200);

        if (data) {
          const myNotifs = data.filter(notif =>
            (portalRole === "admin" || portalRole === "kibar-admin") ||
            notif.target_user === user.id ||
            notif.target_user === user.email ||
            (!notif.target_user && (
              notif.target_role === "all" ||
              notif.target_role === portalRole
            ))
          );
          setNotificationsList(myNotifs);
          if (myNotifs.length > 0) latestNotifIdRef.current = myNotifs[0].id;
        }

        // 2. Real-time Subscription for Instant Alerts
        // Clean up any existing channel with the same name first
        if (notificationChannel) {
            await supabase.removeChannel(notificationChannel);
          }
        
        if (!isActive) return;

        notificationChannel = supabase
          .channel(
            `notif-sync-${user.id}-${Math.random().toString(36).substring(7)}`)
          .on(
            'postgres_changes',
            { event: 'INSERT', table: 'system_notifications', schema: 'public' },
            (payload) => {
              const newNotif = payload.new;
              const isTargeted =
                (portalRole === "admin" || portalRole === "kibar-admin") ||
                newNotif.target_user === user.id ||
                newNotif.target_user === user.email ||
                (!newNotif.target_user && (
                  newNotif.target_role === "all" ||
                  newNotif.target_role === portalRole
                ));

              if (isTargeted) {
                setNotificationsList(prev => {
                  const combined = [newNotif, ...prev];
                  // Strict unique-by-ID filtering to kill the "double card" bug
                  const unique = combined.filter((n, idx, self) => 
                    idx === self.findIndex(t => t.id === n.id)
                  );
                  if (unique.length === prev.length && !prev.some(n => n.id === newNotif.id)) {
                     // This means it was filtered out or something weird happened
                  }
                  return unique;
                });
                // Show OS push notification via service worker
                if (typeof Notification !== 'undefined' && Notification.permission === 'granted' && 'serviceWorker' in navigator) {
                  navigator.serviceWorker.ready.then(reg => {
                    const notifTitle = newNotif.title || 'Mauze Tahfeez Update';
                    const notifBody = newNotif.body || '';
                    const redirectPath = newNotif.redirect_page || '';
                    reg.showNotification(notifTitle, {
                      body: notifBody,
                      icon: '/LOGO ATFAAL.png',
                      badge: '/LOGO ATFAAL.png',
                      vibrate: [200, 100, 200],
                      data: {
                        redirectPage: redirectPath,
                        notification_id: newNotif.id,
                        url: redirectPath ? '/?redirectPage=' + encodeURIComponent(redirectPath) : '/'
                      },
                      tag: `mauze-${newNotif.id}`,
                      renotify: true,
                      requireInteraction: true,
                      actions: [
                        { action: 'open', title: 'Open Portal', icon: '/LOGO ATFAAL.png' },
                        { action: 'dismiss', title: 'Dismiss' }
                      ]
                    });
                  }).catch(() => {});
                  import('./fcmService.js').then(mod => mod.default.playPremiumChime()).catch(() => {});
                }
              }
            }
          )
          .on(
            'postgres_changes',
            { event: '*', table: 'weekly_results', schema: 'public' },
            (payload) => {
              console.log("Real-time result update:", payload.eventType, payload.new?.student_id);
              
              if (payload.eventType === 'INSERT' && portalRole === "parents") {
                showAction("success", "A new progress report has been submitted!");
              }
              
              loadPortalData(portalRole, user, null, { silent: true });
            }
          )
          .on(
            'postgres_changes',
            { event: '*', table: 'parent_report_views', schema: 'public' },
            (payload) => {
              console.log("Real-time parent view update:", payload.eventType, payload.new?.student_id);
              loadPortalData(portalRole, user, null, { silent: true });
            }
          )
          .on(
            'postgres_changes',
            { event: 'INSERT', table: 'student_daily_attendance', schema: 'public' },
            (payload) => {
              if (portalRole === "parents") {
                const rec = payload.new;
                const todayStr = getToday();
                if (rec?.attendance_date === todayStr) {
                  console.log("Real-time attendance INSERT:", rec);
                  setParentData(prev => {
                    if (!prev) return prev;
                    const allIds = prev.studentProfile?.allIds ||
                      (prev.studentProfile?.student_id ? [String(prev.studentProfile.student_id)] : []);
                    const isForThisStudent = allIds.some(id =>
                      String(id).trim().toLowerCase() === String(rec.student_id || "").trim().toLowerCase()
                    );
                    if (!isForThisStudent) return prev;
                    showAction("info", "Attendance marked ✓");
                    return { ...prev, attendance: rec };
                  });
                }
              }
            }
          )
          .on(
            'postgres_changes',
            { event: 'UPDATE', table: 'student_daily_attendance', schema: 'public' },
            (payload) => {
              if (portalRole === "parents") {
                const rec = payload.new;
                const todayStr = getToday();
                if (rec?.attendance_date === todayStr) {
                  console.log("Real-time attendance UPDATE:", rec);
                  setParentData(prev => {
                    if (!prev) return prev;
                    const allIds = prev.studentProfile?.allIds ||
                      (prev.studentProfile?.student_id ? [String(prev.studentProfile.student_id)] : []);
                    const isForThisStudent = allIds.some(id =>
                      String(id).trim().toLowerCase() === String(rec.student_id || "").trim().toLowerCase()
                    );
                    if (!isForThisStudent) return prev;
                    return { ...prev, attendance: rec };
                  });
                }
              }
            }
          );
        
        notificationChannel.subscribe((status) => {
          if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT') {
            // Realtime may be blocked (ad-blocker/firewall) or slow — silently fall
            // back to periodic silent refreshes so updates still arrive.
          }
        });
      } catch (err) {
        console.error("Notification setup error:", err);
      }
    };
    
    setupNotifications();

    return () => {
      isActive = false;
      if (notificationChannel) {
        supabase.removeChannel(notificationChannel);
      }
    };
  }, [user, portalRole]);

  // Client-side scheduler: process due scheduled notifications every 30s
  // (falls back if pg_cron is not enabled on the Supabase project)
  useEffect(() => {
    if (!user || (portalRole !== "admin" && portalRole !== "kibar-admin")) return;
    let isActive = true;

    const processDueNotifications = async () => {
      try {
        const { data: dueNotifs, error } = await supabase
          .from("scheduled_notifications")
          .select("*")
          .eq("is_active", true)
          .lte("next_send_at", new Date().toISOString())
          .limit(10);

        if (error || !dueNotifs?.length) return;

        for (const notif of dueNotifs) {
          if (!isActive) break;

          await broadcastNotification(
            notif.title,
            notif.body,
            notif.target_role === "user" ? notif.target_role : notif.target_role || "all",
            notif.target_user || null,
            notif.redirect_page || "Inbox",
            false,
            notif.file_url || null
          );

          const nextSend = calculateNextSendTime(
            notif.schedule_type,
            notif.schedule_time?.substring(0, 5) || "09:00",
            notif.schedule_day
          );

          await supabase
            .from("scheduled_notifications")
            .update({
              last_sent_at: new Date().toISOString(),
              next_send_at: nextSend,
              updated_at: new Date().toISOString(),
            })
            .eq("id", notif.id);
        }

        fetchScheduledNotifs();
      } catch (e) {
        console.warn("Scheduled notification processor error:", e);
      }
    };

    processDueNotifications();
    const interval = setInterval(processDueNotifications, 30000);

    return () => {
      isActive = false;
      clearInterval(interval);
    };
  }, [user, portalRole]);

